__CR('t:compiler',[{"t":"언어는 어떻게 실행되나","l":[{"t":"번역과 실행","q":[{"t":"choice","k":"구분","q":"C 언어는 주로 어떤 방식으로 실행되나요?","o":["컴파일","인터프리트","둘 다 아님","암호화"],"a":0,"ex":"C 는 컴파일해서 실행 파일을 만듭니다."},{"t":"choice","k":"구분","q":"Python 은 주로 어떤 방식인가요?","o":["컴파일","인터프리트","기계어 직접 작성","수동 번역"],"a":1,"ex":"Python 은 대표적인 인터프리터 언어입니다."}],"th":{"sum":"소스코드는 전체를 미리 번역하는 **컴파일러**나 한 줄씩 실행하는 **인터프리터**로 돌아가며, 컴파일은 `어휘 분석`→`구문 분석`을 거쳐 `AST`를 만든다.","body":[{"h":"번역과 실행 방식","t":"컴파일러는 소스코드 전체를 기계어로 미리 번역해 실행 파일을 만든다. C 언어가 대표적으로 이 방식이다. 인터프리터는 코드를 한 줄씩 해석하며 바로 실행하는데, Python이 주로 이 방식(바이트코드로 컴파일 후 VM이 해석)이다. 컴파일 방식은 실행이 빠르고, 인터프리터 방식은 즉시 실행·이식성이 좋다."},{"h":"컴파일 단계","t":"컴파일러는 먼저 소스코드를 의미 있는 최소 단위인 토큰으로 쪼갠다. 이 단계가 어휘 분석(lexical analysis, 토큰화)이다. 다음으로 토큰들을 문법 규칙에 맞춰 트리 구조로 엮는 구문 분석(parsing)을 거친다. 그 결과 만들어지는 프로그램의 구조 트리를 추상 구문 트리(AST, Abstract Syntax Tree)라 부른다."}],"code":{"c":"# 어휘 분석: x = 1 + 2\n[ID:x] [=] [NUM:1] [+] [NUM:2]\n# 구문 분석 결과(AST)\n  =\n / \\\nx   +\n   / \\\n  1   2","cap":"토큰 → 파싱 → AST 흐름"},"key":["전체 미리 번역 = 컴파일러(C), 한 줄씩 실행 = 인터프리터(Python)","토큰으로 쪼개기 = 어휘 분석(토큰화)","문법 트리로 엮기 = 구문 분석(파싱), 결과 = AST"]}},{"t":"컴파일 단계","q":[{"t":"choice","k":"단계","q":"소스코드를 의미 있는 최소 단위(토큰)로 쪼개는 단계는?","o":["어휘 분석(lexing)","실행","배포","압축"],"a":0,"ex":"렉서(lexer)가 코드를 토큰 열로 나눕니다."},{"t":"choice","k":"용어","q":"파싱 결과로 만들어지는 프로그램의 구조 트리를 뭐라 하나요?","o":["AST(추상 구문 트리)","B-트리","힙","리스트"],"a":0,"ex":"AST 는 코드의 문법 구조를 나무 형태로 표현합니다."}],"th":{"sum":"소스코드는 전체를 미리 번역하는 **컴파일러**나 한 줄씩 실행하는 **인터프리터**로 돌아가며, 컴파일은 `어휘 분석`→`구문 분석`을 거쳐 `AST`를 만든다.","body":[{"h":"번역과 실행 방식","t":"컴파일러는 소스코드 전체를 기계어로 미리 번역해 실행 파일을 만든다. C 언어가 대표적으로 이 방식이다. 인터프리터는 코드를 한 줄씩 해석하며 바로 실행하는데, Python이 주로 이 방식(바이트코드로 컴파일 후 VM이 해석)이다. 컴파일 방식은 실행이 빠르고, 인터프리터 방식은 즉시 실행·이식성이 좋다."},{"h":"컴파일 단계","t":"컴파일러는 먼저 소스코드를 의미 있는 최소 단위인 토큰으로 쪼갠다. 이 단계가 어휘 분석(lexical analysis, 토큰화)이다. 다음으로 토큰들을 문법 규칙에 맞춰 트리 구조로 엮는 구문 분석(parsing)을 거친다. 그 결과 만들어지는 프로그램의 구조 트리를 추상 구문 트리(AST, Abstract Syntax Tree)라 부른다."}],"code":{"c":"# 어휘 분석: x = 1 + 2\n[ID:x] [=] [NUM:1] [+] [NUM:2]\n# 구문 분석 결과(AST)\n  =\n / \\\nx   +\n   / \\\n  1   2","cap":"토큰 → 파싱 → AST 흐름"},"key":["전체 미리 번역 = 컴파일러(C), 한 줄씩 실행 = 인터프리터(Python)","토큰으로 쪼개기 = 어휘 분석(토큰화)","문법 트리로 엮기 = 구문 분석(파싱), 결과 = AST"]}}]},{"t":"어휘 분석·구문 분석과 AST","l":[{"t":"어휘 분석과 토큰","q":[{"t":"choice","k":"cmp-lex-token1","q":"어휘 분석기(lexer)의 입력과 출력을 올바르게 짝지은 것은?","ex":"어휘 분석은 파이프라인의 가장 앞단으로 소스 코드의 문자들을 읽어 토큰 열을 만든다. 토큰 열을 받아 트리를 만드는 것은 다음 단계인 구문 분석의 역할이다.","o":["입력: 토큰 열 / 출력: AST","입력: 문자 스트림 / 출력: 토큰 열","입력: AST / 출력: 중간 표현(IR)","입력: 기계어 / 출력: 소스 코드"],"a":1},{"t":"choice","k":"cmp-lex-token3","q":"다음 중 어휘 분석 단계에서 발견되는 오류는?","ex":"닫히지 않은 문자열이나 언어에 존재하지 않는 잘못된 문자는 토큰을 만들 수 없으므로 어휘 오류다. 선언되지 않은 변수, 타입 불일치, 인자 개수 불일치는 모두 훨씬 뒤인 의미 분석 단계에서 잡힌다.","o":["선언되지 않은 변수 total을 사용했다","정수에 문자열을 더해 타입이 맞지 않는다","문자열 리터럴의 따옴표가 닫히지 않았다","함수를 호출하며 인자 개수를 잘못 넘겼다"],"a":2},{"t":"choice","k":"cmp-lex-token4","q":"토큰의 모양을 기술하는 데 정규식과 유한 오토마타로 충분한 이유는?","ex":"식별자, 숫자, 연산자 같은 개별 토큰의 패턴에는 임의 깊이의 중첩이 없어 정규 언어로 충분하다. 반대로 중첩 괄호처럼 깊이를 세야 하는 구조는 유한 오토마타로 표현할 수 없어서 문맥자유문법이 필요하고, 그래서 구문 분석 단계가 따로 존재한다.","o":["토큰 하나하나의 패턴은 재귀적 중첩이 없는 정규 언어이기 때문","정규식이 문맥자유문법보다 표현력이 강하기 때문","모든 프로그래밍 언어의 전체 문법이 정규 언어이기 때문","유한 오토마타가 임의 깊이의 괄호 짝을 셀 수 있기 때문"],"a":0},{"t":"input","k":"cmp-lex-token5","q":"어휘 분석기가 보통 토큰으로 만들지 않고 버리는 두 가지 요소 중, 코드에 설명을 남기기 위해 쓰는 것은 무엇인가? (한 단어, 한국어로)","ex":"공백과 주석은 프로그램의 의미에 영향을 주지 않으므로 대부분의 언어에서 어휘 분석기가 건너뛴다. 그래서 파서는 주석의 존재를 아예 알지 못한다. 다만 문서 생성 도구를 위해 주석을 별도로 보관하는 구현도 있다.","a":["주석"]},{"t":"choice","k":"cmp-lex-token6","q":"다음 코드 한 줄을 어휘 분석했을 때 만들어지는 토큰 개수는? (세미콜론 포함)","ex":"sum, =, a, +, 10, ; 로 총 6개의 토큰이 나온다. 토큰 사이의 공백은 토큰 경계를 알려줄 뿐 그 자체로는 토큰이 되지 않고 버려진다.","code":"sum = a + 10;","o":["4개","5개","6개","7개"],"a":2}],"th":{"sum":"컴파일러의 앞단(front-end)은 소스 문자열을 토큰으로 쪼개고, 문법에 따라 트리로 조립한다. 그 결과물인 AST가 뒤따르는 모든 단계의 기반이 된다.","body":[{"h":"어휘 분석: 문자에서 토큰으로","t":"어휘 분석기(lexer/scanner)는 소스 코드의 문자 스트림을 읽어 의미 있는 최소 단위인 토큰으로 자른다. 토큰은 보통 (종류, 렉심) 쌍으로 표현되며, 예를 들어 count라는 문자열은 (IDENT, \"count\")가 된다. 공백과 주석은 대개 여기서 버려지고 파서까지 전달되지 않는다. 토큰의 모양은 정규 언어로 기술할 수 있어서 정규식과 유한 오토마타(DFA)로 구현된다."},{"h":"구문 분석: 토큰에서 트리로","t":"구문 분석기(parser)는 토큰 열이 언어의 문법에 맞는지 검사하며 트리를 만든다. 프로그래밍 언어의 문법은 정규 언어보다 강한 문맥자유문법(CFG)으로 기술하는데, 중첩된 괄호나 블록처럼 재귀적인 구조를 정규식으로는 표현할 수 없기 때문이다. 하향식 방식에는 재귀 하강 파서와 LL 파서가 있고, 상향식 방식에는 LR·LALR 파서가 있다. 연산자 우선순위와 결합성은 문법을 계층적으로 쓰거나 우선순위 등반(precedence climbing)·Pratt 파서로 처리한다."},{"h":"파스 트리와 AST의 차이","t":"파스 트리(구체 구문 트리)는 문법이 사용한 모든 기호를 그대로 담기 때문에 괄호, 세미콜론, 중간 비단말까지 전부 노드로 남는다. AST(추상 구문 트리)는 이런 문법 잡음을 걷어내고 프로그램의 구조만 남긴 형태다. 예를 들어 (1 + 2) * 3의 AST에는 괄호 노드가 없고, 대신 곱셈 노드의 왼쪽 자식이 덧셈 노드라는 구조 자체가 우선순위를 표현한다. 이후 단계는 거의 항상 파스 트리가 아니라 AST 위에서 동작한다."}],"code":{"c":"소스:  x = (1 + 2) * 3;\n\n토큰:  (IDENT,\"x\") (EQ,\"=\") (LPAREN,\"(\") (INT,\"1\")\n       (PLUS,\"+\") (INT,\"2\") (RPAREN,\")\") (STAR,\"*\")\n       (INT,\"3\") (SEMI,\";\")\n\nAST:   Assign\n        ├── Var(x)\n        └── Mul\n            ├── Add\n            │   ├── Int(1)\n            │   └── Int(2)\n            └── Int(3)","cap":"같은 소스의 토큰 목록과 AST — 괄호와 세미콜론은 AST에 남지 않는다."},"key":["토큰은 (종류, 렉심) 쌍이고 공백·주석은 보통 어휘 분석에서 버려진다","토큰은 정규 언어, 프로그램 구조는 문맥자유문법으로 기술한다","AST는 괄호·세미콜론 같은 문법 잡음을 버리고 구조만 남긴다"]}},{"t":"구문 분석과 문법","q":[{"t":"choice","k":"cmp-parse-gram2","q":"재귀 하강 파서(recursive descent)에 대한 설명으로 옳은 것은?","ex":"재귀 하강은 대표적인 하향식(LL) 기법으로, 각 비단말에 대응하는 함수를 손으로 작성해 시작 기호에서부터 아래로 내려간다. 스택에 쌓아 축약하며 올라가는 것은 LR/LALR 계열의 상향식 파싱이다.","o":["문법의 비단말마다 함수를 두고 시작 기호부터 내려가며 파싱하는 하향식 방식이다","토큰을 스택에 쌓아 규칙으로 축약해 올라가는 상향식 방식이다","AST 대신 기계어를 직접 출력하는 방식이다","문법 없이 토큰의 빈도만으로 구조를 추측하는 방식이다"],"a":0},{"t":"choice","k":"cmp-parse-gram3","q":"dangling else 문제는 무엇의 대표적인 예인가?","ex":"if a then if b then s1 else s2 에서 else가 어느 if에 붙는지 문법만으로는 결정되지 않아 파스 트리가 두 개 나온다. 이것이 모호한 문법의 고전적 예이며, 보통 \"else는 가장 가까운 if에 붙는다\"는 규칙을 문법이나 파서에 추가해 해소한다.","o":["어휘 분석에서 발생하는 토큰 충돌","하나의 토큰 열이 둘 이상의 파스 트리를 갖는 모호한 문법","레지스터가 부족해 값을 메모리로 밀어내는 상황","런타임에 타입이 바뀌는 동적 타입 언어의 특성"],"a":1},{"t":"choice","k":"cmp-parse-gram4","q":"표현식에서 연산자 우선순위와 결합성을 처리하는 방법으로 옳지 않은 것은?","ex":"어휘 분석기는 소스에 나타난 순서대로 토큰을 만들 뿐이고 우선순위 개념 자체가 없다. 우선순위와 결합성은 문법 계층화, 우선순위 등반, Pratt 파서처럼 구문 분석 단계의 기법으로 처리한다.","o":["문법을 expr / term / factor처럼 계층으로 나눠 우선순위를 인코딩한다","우선순위 등반(precedence climbing) 알고리즘을 사용한다","Pratt 파서로 토큰마다 결합 세기를 부여해 처리한다","어휘 분석기가 * 토큰을 + 토큰보다 먼저 만들어 우선순위를 정한다"],"a":3},{"t":"input","k":"cmp-parse-gram5","q":"LR·LALR처럼 토큰을 스택에 쌓았다가 규칙으로 축약하며 트리를 아래에서 위로 만드는 파싱 방식을 무엇이라 하는가? (한국어 세 글자, 예: OO식)","ex":"LR·LALR 계열은 잎에서 뿌리 방향으로 트리를 만들기 때문에 상향식(bottom-up) 파싱이라 부른다. 반대로 재귀 하강과 LL은 시작 기호에서 내려가는 하향식(top-down) 방식이다. 상향식은 다룰 수 있는 문법의 범위가 더 넓다.","a":["상향식"]},{"t":"choice","k":"cmp-parse-gram6","q":"다음 문법으로 1 + 2 * 3 을 파싱할 때 만들어지는 구조는?","ex":"term이 expr보다 아래 계층에 있어서 곱셈이 항상 더 단단히 묶이고, 결과적으로 1 + (2 * 3) 구조가 된다. 이렇게 문법을 계층으로 나누는 것만으로 우선순위를 표현할 수 있고, 이 문법은 모호하지 않다.","code":"expr   -&gt; expr '+' term | term\nterm   -&gt; term '*' factor | factor\nfactor -&gt; NUM | '(' expr ')'","o":["곱셈이 덧셈의 오른쪽 피연산자가 되어 1 + (2 * 3)","덧셈이 먼저 묶여 (1 + 2) * 3","문법이 모호해 두 구조 모두 유효하다","우선순위 정보가 없어 파싱이 실패한다"],"a":0}],"th":{"sum":"컴파일러의 앞단(front-end)은 소스 문자열을 토큰으로 쪼개고, 문법에 따라 트리로 조립한다. 그 결과물인 AST가 뒤따르는 모든 단계의 기반이 된다.","body":[{"h":"어휘 분석: 문자에서 토큰으로","t":"어휘 분석기(lexer/scanner)는 소스 코드의 문자 스트림을 읽어 의미 있는 최소 단위인 토큰으로 자른다. 토큰은 보통 (종류, 렉심) 쌍으로 표현되며, 예를 들어 count라는 문자열은 (IDENT, \"count\")가 된다. 공백과 주석은 대개 여기서 버려지고 파서까지 전달되지 않는다. 토큰의 모양은 정규 언어로 기술할 수 있어서 정규식과 유한 오토마타(DFA)로 구현된다."},{"h":"구문 분석: 토큰에서 트리로","t":"구문 분석기(parser)는 토큰 열이 언어의 문법에 맞는지 검사하며 트리를 만든다. 프로그래밍 언어의 문법은 정규 언어보다 강한 문맥자유문법(CFG)으로 기술하는데, 중첩된 괄호나 블록처럼 재귀적인 구조를 정규식으로는 표현할 수 없기 때문이다. 하향식 방식에는 재귀 하강 파서와 LL 파서가 있고, 상향식 방식에는 LR·LALR 파서가 있다. 연산자 우선순위와 결합성은 문법을 계층적으로 쓰거나 우선순위 등반(precedence climbing)·Pratt 파서로 처리한다."},{"h":"파스 트리와 AST의 차이","t":"파스 트리(구체 구문 트리)는 문법이 사용한 모든 기호를 그대로 담기 때문에 괄호, 세미콜론, 중간 비단말까지 전부 노드로 남는다. AST(추상 구문 트리)는 이런 문법 잡음을 걷어내고 프로그램의 구조만 남긴 형태다. 예를 들어 (1 + 2) * 3의 AST에는 괄호 노드가 없고, 대신 곱셈 노드의 왼쪽 자식이 덧셈 노드라는 구조 자체가 우선순위를 표현한다. 이후 단계는 거의 항상 파스 트리가 아니라 AST 위에서 동작한다."}],"code":{"c":"소스:  x = (1 + 2) * 3;\n\n토큰:  (IDENT,\"x\") (EQ,\"=\") (LPAREN,\"(\") (INT,\"1\")\n       (PLUS,\"+\") (INT,\"2\") (RPAREN,\")\") (STAR,\"*\")\n       (INT,\"3\") (SEMI,\";\")\n\nAST:   Assign\n        ├── Var(x)\n        └── Mul\n            ├── Add\n            │   ├── Int(1)\n            │   └── Int(2)\n            └── Int(3)","cap":"같은 소스의 토큰 목록과 AST — 괄호와 세미콜론은 AST에 남지 않는다."},"key":["토큰은 (종류, 렉심) 쌍이고 공백·주석은 보통 어휘 분석에서 버려진다","토큰은 정규 언어, 프로그램 구조는 문맥자유문법으로 기술한다","AST는 괄호·세미콜론 같은 문법 잡음을 버리고 구조만 남긴다"]}},{"t":"AST의 구조와 순회","q":[{"t":"choice","k":"cmp-ast-tree2","q":"표현식 (2 + 3) * 4 의 AST에 대한 설명으로 옳은 것은?","ex":"괄호는 파싱 중 묶는 순서를 지시한 뒤 역할을 다하므로 AST에는 남지 않는다. 대신 곱셈이 루트이고 왼쪽 자식이 Add(2,3), 오른쪽 자식이 Int(4)라는 트리 모양 자체가 원래 괄호가 표현하던 의미를 담는다.","o":["괄호 노드가 루트가 되고 그 아래에 덧셈과 곱셈이 놓인다","괄호 노드는 없고 곱셈 노드의 왼쪽 자식이 덧셈 노드다","괄호 노드는 없고 덧셈 노드의 왼쪽 자식이 곱셈 노드다","AST는 표현식을 다루지 않으므로 트리가 만들어지지 않는다"],"a":1},{"t":"input","k":"cmp-ast-tree4","q":"표현식 1 - 2 - 3 을 왼쪽 결합으로 파싱했을 때, AST 루트인 뺄셈 노드의 오른쪽 자식이 되는 정수 리터럴은 무엇인가? (숫자로)","ex":"왼쪽 결합이므로 (1 - 2) - 3 으로 묶이고, 바깥쪽 뺄셈이 루트가 된다. 따라서 루트의 왼쪽 자식은 Sub(1,2)이고 오른쪽 자식은 Int(3)이다. 만약 오른쪽 결합이었다면 루트의 왼쪽 자식이 Int(1)이 되어 결과값도 달라진다.","a":["3"]},{"t":"choice","k":"cmp-ast-tree5","q":"다음 AST 스케치가 나타내는 원본 표현식으로 가장 알맞은 것은?","ex":"덧셈이 루트이고 곱셈이 그 오른쪽 자식이므로 곱셈이 더 단단히 묶여 있다. 이는 우선순위 규칙이 그대로 적용된 1 + 2 * 3 에 해당한다. (1 + 2) * 3 이라면 곱셈이 루트가 되어 트리 모양이 뒤집힌다.","code":"Add\n├── Int(1)\n└── Mul\n    ├── Int(2)\n    └── Int(3)","o":["(1 + 2) * 3","1 + 2 * 3","1 * 2 + 3","(1 * 2) + (3 * 1)"],"a":1}],"th":{"sum":"컴파일러의 앞단(front-end)은 소스 문자열을 토큰으로 쪼개고, 문법에 따라 트리로 조립한다. 그 결과물인 AST가 뒤따르는 모든 단계의 기반이 된다.","body":[{"h":"어휘 분석: 문자에서 토큰으로","t":"어휘 분석기(lexer/scanner)는 소스 코드의 문자 스트림을 읽어 의미 있는 최소 단위인 토큰으로 자른다. 토큰은 보통 (종류, 렉심) 쌍으로 표현되며, 예를 들어 count라는 문자열은 (IDENT, \"count\")가 된다. 공백과 주석은 대개 여기서 버려지고 파서까지 전달되지 않는다. 토큰의 모양은 정규 언어로 기술할 수 있어서 정규식과 유한 오토마타(DFA)로 구현된다."},{"h":"구문 분석: 토큰에서 트리로","t":"구문 분석기(parser)는 토큰 열이 언어의 문법에 맞는지 검사하며 트리를 만든다. 프로그래밍 언어의 문법은 정규 언어보다 강한 문맥자유문법(CFG)으로 기술하는데, 중첩된 괄호나 블록처럼 재귀적인 구조를 정규식으로는 표현할 수 없기 때문이다. 하향식 방식에는 재귀 하강 파서와 LL 파서가 있고, 상향식 방식에는 LR·LALR 파서가 있다. 연산자 우선순위와 결합성은 문법을 계층적으로 쓰거나 우선순위 등반(precedence climbing)·Pratt 파서로 처리한다."},{"h":"파스 트리와 AST의 차이","t":"파스 트리(구체 구문 트리)는 문법이 사용한 모든 기호를 그대로 담기 때문에 괄호, 세미콜론, 중간 비단말까지 전부 노드로 남는다. AST(추상 구문 트리)는 이런 문법 잡음을 걷어내고 프로그램의 구조만 남긴 형태다. 예를 들어 (1 + 2) * 3의 AST에는 괄호 노드가 없고, 대신 곱셈 노드의 왼쪽 자식이 덧셈 노드라는 구조 자체가 우선순위를 표현한다. 이후 단계는 거의 항상 파스 트리가 아니라 AST 위에서 동작한다."}],"code":{"c":"소스:  x = (1 + 2) * 3;\n\n토큰:  (IDENT,\"x\") (EQ,\"=\") (LPAREN,\"(\") (INT,\"1\")\n       (PLUS,\"+\") (INT,\"2\") (RPAREN,\")\") (STAR,\"*\")\n       (INT,\"3\") (SEMI,\";\")\n\nAST:   Assign\n        ├── Var(x)\n        └── Mul\n            ├── Add\n            │   ├── Int(1)\n            │   └── Int(2)\n            └── Int(3)","cap":"같은 소스의 토큰 목록과 AST — 괄호와 세미콜론은 AST에 남지 않는다."},"key":["토큰은 (종류, 렉심) 쌍이고 공백·주석은 보통 어휘 분석에서 버려진다","토큰은 정규 언어, 프로그램 구조는 문맥자유문법으로 기술한다","AST는 괄호·세미콜론 같은 문법 잡음을 버리고 구조만 남긴다"]}}]},{"t":"의미 분석과 타입 검사","l":[{"t":"심볼 테이블과 스코프","q":[{"t":"choice","k":"cmp-sem-sym2","q":"정적(렉시컬) 스코프와 동적 스코프의 차이로 옳은 것은?","ex":"정적 스코프에서는 함수가 어디에 쓰여 있는지가 이름의 의미를 결정하므로 코드만 보고 판단할 수 있다. 동적 스코프에서는 누가 호출했는지에 따라 같은 이름이 다른 변수를 가리켜 추론이 어렵고, 그래서 현대 언어 대부분은 정적 스코프를 택한다.","o":["정적 스코프는 소스 코드의 중첩 구조로, 동적 스코프는 실행 중 호출 스택으로 이름의 의미가 결정된다","정적 스코프는 실행 중에만 결정되고 동적 스코프는 컴파일 타임에 결정된다","정적 스코프는 전역 변수만, 동적 스코프는 지역 변수만 다룬다","둘은 이름만 다를 뿐 결과가 항상 같다"],"a":0},{"t":"choice","k":"cmp-sem-sym3","q":"중첩 블록에서 이름을 조회할 때의 표준적인 순서는?","ex":"스코프 스택의 꼭대기(가장 안쪽)부터 검색해 처음 발견한 선언을 사용하며, 이 때문에 안쪽 선언이 바깥 선언을 가린다(shadowing). 안쪽에 같은 이름을 다시 선언하는 것 자체는 오류가 아니라 정상적인 가리기다.","o":["전역 스코프부터 시작해 안쪽으로 내려가며 찾는다","가장 안쪽 스코프부터 바깥쪽으로 올라가며 찾고 처음 만난 선언을 쓴다","모든 스코프를 뒤져 선언이 둘 이상이면 오류로 처리한다","선언 위치와 무관하게 알파벳 순으로 우선순위를 정한다"],"a":1},{"t":"input","k":"cmp-sem-sym4","q":"다음 코드에서 print(x)가 출력하는 값은 무엇인가? (정적 스코프 기준, 숫자로)","ex":"안쪽 블록의 x = 20 은 그 블록 안에서만 유효하고, 블록이 닫히면 해당 스코프가 스택에서 제거된다. print(x)는 다시 전역 스코프의 x를 보게 되므로 10이 출력된다.","code":"let x = 10;\n{\n    let x = 20;\n}\nprint(x);","a":["10"]},{"t":"choice","k":"cmp-sem-sym5","q":"다음 코드에서 컴파일러가 보고할 오류와 그 단계로 옳은 것은?","ex":"total = total + 1 은 토큰으로 잘 나뉘고 문법에도 완벽히 맞으므로 어휘·구문 분석은 통과한다. 문제는 total이라는 이름이 심볼 테이블에 없다는 것이고, 이는 이름 해석을 담당하는 의미 분석 단계에서 잡힌다.","code":"int main() {\n    total = total + 1;\n    return 0;\n}","o":["어휘 분석 단계의 잘못된 문자 오류","구문 분석 단계의 문법 오류","의미 분석 단계의 선언되지 않은 변수 오류","코드 생성 단계의 레지스터 부족 오류"],"a":2}],"th":{"sum":"문법에 맞는 코드라고 해서 의미가 통하는 것은 아니다. 의미 분석은 심볼 테이블로 이름을 해석하고 타입을 검사해 실행 전에 잡을 수 있는 오류를 걸러낸다.","body":[{"h":"심볼 테이블과 이름 해석","t":"심볼 테이블은 프로그램에 등장하는 이름을 그 선언 정보(타입, 종류, 위치)에 연결하는 자료구조다. 블록이 열릴 때마다 새 스코프를 밀어 넣고 닫힐 때 꺼내는 스택 구조로 흔히 구현한다. 이름을 찾을 때는 가장 안쪽 스코프부터 바깥으로 올라가며 검색하고, 끝까지 못 찾으면 \"선언되지 않은 변수\" 오류가 된다. 대부분의 현대 언어는 이름의 의미가 소스 코드의 중첩 구조로 결정되는 정적(렉시컬) 스코프를 쓰며, 호출 스택을 따라 결정되는 동적 스코프와 구별된다."},{"h":"타입 검사와 타입 추론","t":"타입 검사기는 AST를 순회하며 각 표현식의 타입을 계산하고 연산이 그 타입에 허용되는지 확인한다. 정수와 문자열을 더하는 것 같은 타입 불일치, 인자 개수나 타입이 맞지 않는 함수 호출이 여기서 걸린다. 타입 추론은 개발자가 어노테이션을 쓰지 않아도 컴파일러가 타입을 스스로 알아내는 기법으로, Hindley-Milner 알고리즘이 대표적이다. 추론이 있다고 해서 동적 타입이 되는 것이 아니라, 여전히 컴파일 타임에 완전한 정적 타입이 부여된다."},{"h":"정적/동적과 강/약은 다른 축","t":"정적 타입은 컴파일 타임에 타입을 검사하고, 동적 타입은 값에 타입표를 붙여 런타임에 검사한다. 이는 강/약 타입과 완전히 다른 축이다. 강한 타입은 몰래 하는 암묵적 변환을 허용하지 않는다는 뜻이라, 파이썬처럼 동적이면서 강한 타입인 언어도 있고 C처럼 정적이면서 상대적으로 약한 언어도 있다. 어느 단계에서 오류가 잡히는지 구분하는 것도 중요하다. 잘못된 문자는 어휘, 짝이 안 맞는 괄호는 구문, 선언되지 않은 변수와 타입 불일치는 의미 분석, 0으로 나누기나 널 참조는 대개 런타임이다."}],"code":{"c":"let x: int = 1;\n{\n    let x: string = \"hi\";   // 안쪽 스코프의 새 x\n    print(x + 1);           // 타입 오류: string + int\n}\nprint(y);                   // 이름 오류: y 미선언\n\n심볼 테이블(안쪽 블록 시점)\n  scope#1 (블록)  : x -> string\n  scope#0 (전역)  : x -> int\n\n조회 x  => 안쪽부터 검색 => string\n조회 y  => 어느 스코프에도 없음 => 오류","cap":"스코프 스택을 안쪽부터 검색하는 이름 해석과, 의미 분석에서 잡히는 두 종류의 오류."},"key":["심볼 테이블은 이름을 선언 정보에 연결하고 스코프는 스택처럼 중첩된다","선언되지 않은 변수·타입 불일치·인자 개수 오류는 의미 분석에서 잡힌다","정적/동적과 강/약 타입은 서로 독립된 축이다"]}},{"t":"타입 검사와 타입 추론","q":[{"t":"choice","k":"cmp-sem-type2","q":"타입 추론(Hindley-Milner 등)에 대한 설명으로 옳은 것은?","ex":"타입 추론은 타입을 없애는 것이 아니라 개발자가 적어야 할 어노테이션을 컴파일러가 대신 유도하는 기법이다. 추론이 끝나면 모든 표현식에 컴파일 타임 타입이 붙으므로 정적 타입 검사의 안전성은 그대로 유지된다.","o":["어노테이션이 없어도 컴파일 타임에 타입을 알아내므로 여전히 정적 타입이다","타입을 런타임까지 미루므로 언어를 동적 타입으로 만든다","타입 검사를 생략해 오류 검출을 포기하는 기법이다","모든 변수의 타입을 자동으로 문자열로 통일한다"],"a":0},{"t":"choice","k":"cmp-sem-type3","q":"다음 코드에서 컴파일러가 보고하는 오류의 종류는?","ex":"add(1, 2, 3) 은 함수 호출 문법으로는 완벽히 유효해서 파서는 아무 문제도 못 느낀다. 심볼 테이블에서 add의 선언을 찾아 매개변수가 2개임을 확인하는 순간, 즉 의미 분석에서 인자 개수 불일치가 드러난다.","code":"int add(int a, int b) { return a + b; }\n\nint main() {\n    return add(1, 2, 3);\n}","o":["구문 분석 단계의 괄호 짝 오류","어휘 분석 단계의 토큰 오류","런타임에만 발견 가능한 오류","의미 분석 단계의 인자 개수 불일치 오류"],"a":3},{"t":"input","k":"cmp-sem-type5","q":"어노테이션 없이도 컴파일러가 표현식의 타입을 스스로 알아내는 기법을 무엇이라 하는가? (한국어로, 예: 타입 OO)","ex":"타입 추론은 변수의 사용 방식으로부터 제약을 모아 풀어내 타입을 결정한다. Hindley-Milner는 이 접근의 대표 알고리즘으로 ML, Haskell 계열 언어의 바탕이 되었고, 현대 언어의 지역 변수 타입 생략 기능도 같은 아이디어의 축소판이다.","a":["타입 추론"]}],"th":{"sum":"문법에 맞는 코드라고 해서 의미가 통하는 것은 아니다. 의미 분석은 심볼 테이블로 이름을 해석하고 타입을 검사해 실행 전에 잡을 수 있는 오류를 걸러낸다.","body":[{"h":"심볼 테이블과 이름 해석","t":"심볼 테이블은 프로그램에 등장하는 이름을 그 선언 정보(타입, 종류, 위치)에 연결하는 자료구조다. 블록이 열릴 때마다 새 스코프를 밀어 넣고 닫힐 때 꺼내는 스택 구조로 흔히 구현한다. 이름을 찾을 때는 가장 안쪽 스코프부터 바깥으로 올라가며 검색하고, 끝까지 못 찾으면 \"선언되지 않은 변수\" 오류가 된다. 대부분의 현대 언어는 이름의 의미가 소스 코드의 중첩 구조로 결정되는 정적(렉시컬) 스코프를 쓰며, 호출 스택을 따라 결정되는 동적 스코프와 구별된다."},{"h":"타입 검사와 타입 추론","t":"타입 검사기는 AST를 순회하며 각 표현식의 타입을 계산하고 연산이 그 타입에 허용되는지 확인한다. 정수와 문자열을 더하는 것 같은 타입 불일치, 인자 개수나 타입이 맞지 않는 함수 호출이 여기서 걸린다. 타입 추론은 개발자가 어노테이션을 쓰지 않아도 컴파일러가 타입을 스스로 알아내는 기법으로, Hindley-Milner 알고리즘이 대표적이다. 추론이 있다고 해서 동적 타입이 되는 것이 아니라, 여전히 컴파일 타임에 완전한 정적 타입이 부여된다."},{"h":"정적/동적과 강/약은 다른 축","t":"정적 타입은 컴파일 타임에 타입을 검사하고, 동적 타입은 값에 타입표를 붙여 런타임에 검사한다. 이는 강/약 타입과 완전히 다른 축이다. 강한 타입은 몰래 하는 암묵적 변환을 허용하지 않는다는 뜻이라, 파이썬처럼 동적이면서 강한 타입인 언어도 있고 C처럼 정적이면서 상대적으로 약한 언어도 있다. 어느 단계에서 오류가 잡히는지 구분하는 것도 중요하다. 잘못된 문자는 어휘, 짝이 안 맞는 괄호는 구문, 선언되지 않은 변수와 타입 불일치는 의미 분석, 0으로 나누기나 널 참조는 대개 런타임이다."}],"code":{"c":"let x: int = 1;\n{\n    let x: string = \"hi\";   // 안쪽 스코프의 새 x\n    print(x + 1);           // 타입 오류: string + int\n}\nprint(y);                   // 이름 오류: y 미선언\n\n심볼 테이블(안쪽 블록 시점)\n  scope#1 (블록)  : x -> string\n  scope#0 (전역)  : x -> int\n\n조회 x  => 안쪽부터 검색 => string\n조회 y  => 어느 스코프에도 없음 => 오류","cap":"스코프 스택을 안쪽부터 검색하는 이름 해석과, 의미 분석에서 잡히는 두 종류의 오류."},"key":["심볼 테이블은 이름을 선언 정보에 연결하고 스코프는 스택처럼 중첩된다","선언되지 않은 변수·타입 불일치·인자 개수 오류는 의미 분석에서 잡힌다","정적/동적과 강/약 타입은 서로 독립된 축이다"]}},{"t":"정적 vs 동적 타입, 오류가 잡히는 단계","q":[{"t":"choice","k":"cmp-sem-stat1","q":"다음 중 정적 타입과 동적 타입의 구분에 대한 서술로 옳은 것은?","ex":"구분의 핵심은 타입 검사가 실행 전에 일어나느냐 실행 중에 일어나느냐다. 타입 추론이 있는 정적 언어는 어노테이션을 거의 안 써도 되고, 동적 언어의 값에도 분명히 타입이 있으며, 강/약 타입은 완전히 별개의 축이다.","o":["정적 타입 언어는 반드시 모든 변수에 타입을 적어야 한다","동적 타입 언어에는 타입이라는 개념 자체가 없다","정적 타입은 컴파일 타임에, 동적 타입은 런타임에 타입을 검사한다","정적 타입 언어는 언제나 강한 타입이고 동적 타입 언어는 언제나 약한 타입이다"],"a":2},{"t":"choice","k":"cmp-sem-stat2","q":"강한 타입(strong typing)이 뜻하는 바로 가장 적절한 것은?","ex":"강/약은 타입 규칙을 얼마나 엄격히 지키는지, 즉 암묵적 변환을 얼마나 허용하는지의 축이다. 파이썬은 동적이지만 \"1\" + 1 을 거부하는 강한 타입이고, C는 정적이지만 포인터와 정수를 캐스팅으로 넘나들 수 있어 상대적으로 약하다.","o":["타입이 맞지 않을 때 몰래 암묵적 변환을 하지 않고 거부한다","타입 검사를 항상 컴파일 타임에 한다","정수 타입의 크기가 항상 64비트다","모든 타입을 개발자가 직접 적어야 한다"],"a":0},{"t":"input","k":"cmp-sem-stat5","q":"\"선언되지 않은 변수\", \"타입 불일치\", \"인자 개수 불일치\"가 공통으로 잡히는 컴파일 단계의 이름은? (한국어로, 예: OO 분석)","ex":"세 오류 모두 코드가 문법적으로는 완전히 유효하지만 의미가 통하지 않는 경우다. 판단에 심볼 테이블과 타입 정보가 필요하므로 구문 분석이 끝난 뒤의 의미 분석 단계에서 처리된다.","a":["의미 분석"]},{"t":"choice","k":"cmp-sem-stat6","q":"동적 타입 언어에서 다음 코드를 실행할 때 일어나는 일은? (n은 실행 중 입력으로 결정)","ex":"동적 타입 검사는 그 연산이 실제로 수행되는 순간에만 일어나므로 실행되지 않은 분기의 타입 오류는 잠복한다. 이것이 정적 타입 검사가 커버리지와 무관하게 오류를 미리 잡아 준다는 장점의 뒷면이다.","code":"if n &gt; 100:\n    print(\"big\" + 1)\nelse:\n    print(\"small\")","o":["n 값과 무관하게 실행 전에 타입 오류가 보고된다","n이 100 이하라 해당 분기가 실행되지 않으면 오류가 드러나지 않는다","문자열과 정수를 더하는 코드는 어떤 언어에서도 문법 오류다","인터프리터가 자동으로 1을 문자열로 바꿔 항상 정상 동작한다"],"a":1}],"th":{"sum":"문법에 맞는 코드라고 해서 의미가 통하는 것은 아니다. 의미 분석은 심볼 테이블로 이름을 해석하고 타입을 검사해 실행 전에 잡을 수 있는 오류를 걸러낸다.","body":[{"h":"심볼 테이블과 이름 해석","t":"심볼 테이블은 프로그램에 등장하는 이름을 그 선언 정보(타입, 종류, 위치)에 연결하는 자료구조다. 블록이 열릴 때마다 새 스코프를 밀어 넣고 닫힐 때 꺼내는 스택 구조로 흔히 구현한다. 이름을 찾을 때는 가장 안쪽 스코프부터 바깥으로 올라가며 검색하고, 끝까지 못 찾으면 \"선언되지 않은 변수\" 오류가 된다. 대부분의 현대 언어는 이름의 의미가 소스 코드의 중첩 구조로 결정되는 정적(렉시컬) 스코프를 쓰며, 호출 스택을 따라 결정되는 동적 스코프와 구별된다."},{"h":"타입 검사와 타입 추론","t":"타입 검사기는 AST를 순회하며 각 표현식의 타입을 계산하고 연산이 그 타입에 허용되는지 확인한다. 정수와 문자열을 더하는 것 같은 타입 불일치, 인자 개수나 타입이 맞지 않는 함수 호출이 여기서 걸린다. 타입 추론은 개발자가 어노테이션을 쓰지 않아도 컴파일러가 타입을 스스로 알아내는 기법으로, Hindley-Milner 알고리즘이 대표적이다. 추론이 있다고 해서 동적 타입이 되는 것이 아니라, 여전히 컴파일 타임에 완전한 정적 타입이 부여된다."},{"h":"정적/동적과 강/약은 다른 축","t":"정적 타입은 컴파일 타임에 타입을 검사하고, 동적 타입은 값에 타입표를 붙여 런타임에 검사한다. 이는 강/약 타입과 완전히 다른 축이다. 강한 타입은 몰래 하는 암묵적 변환을 허용하지 않는다는 뜻이라, 파이썬처럼 동적이면서 강한 타입인 언어도 있고 C처럼 정적이면서 상대적으로 약한 언어도 있다. 어느 단계에서 오류가 잡히는지 구분하는 것도 중요하다. 잘못된 문자는 어휘, 짝이 안 맞는 괄호는 구문, 선언되지 않은 변수와 타입 불일치는 의미 분석, 0으로 나누기나 널 참조는 대개 런타임이다."}],"code":{"c":"let x: int = 1;\n{\n    let x: string = \"hi\";   // 안쪽 스코프의 새 x\n    print(x + 1);           // 타입 오류: string + int\n}\nprint(y);                   // 이름 오류: y 미선언\n\n심볼 테이블(안쪽 블록 시점)\n  scope#1 (블록)  : x -> string\n  scope#0 (전역)  : x -> int\n\n조회 x  => 안쪽부터 검색 => string\n조회 y  => 어느 스코프에도 없음 => 오류","cap":"스코프 스택을 안쪽부터 검색하는 이름 해석과, 의미 분석에서 잡히는 두 종류의 오류."},"key":["심볼 테이블은 이름을 선언 정보에 연결하고 스코프는 스택처럼 중첩된다","선언되지 않은 변수·타입 불일치·인자 개수 오류는 의미 분석에서 잡힌다","정적/동적과 강/약 타입은 서로 독립된 축이다"]}}]},{"t":"최적화·코드 생성과 실행 방식","l":[{"t":"IR과 최적화 기법","q":[{"t":"choice","k":"cmp-opt-ir2","q":"최적화가 지켜야 하는 가장 근본적인 원칙은?","ex":"최적화는 semantics-preserving 변환이어야 하며, 같은 입력에 대해 관찰 가능한 결과가 달라지면 그것은 최적화가 아니라 버그다. 인라이닝처럼 코드 크기를 오히려 늘리는 최적화도 있으므로 줄 수 감소는 목표가 아니다.","o":["코드 줄 수를 반드시 줄여야 한다","프로그램의 관찰 가능한 의미를 보존해야 한다","실행 시간을 항상 절반 이하로 줄여야 한다","필요하다면 프로그램의 의미를 바꿔서라도 속도를 높여야 한다"],"a":1},{"t":"choice","k":"cmp-opt-ir4","q":"다음 변환에 사용된 최적화 기법 두 가지를 순서대로 고르면?","ex":"3 * 4 를 컴파일 타임에 계산해 12로 바꾼 것이 상수 접기다. c는 계산 후 아무 곳에서도 사용되지 않아 결과에 영향을 주지 않으므로 죽은 코드 제거로 삭제된다.","code":"변환 전:            변환 후:\n  a = 3 * 4;          a = 12;\n  b = a + 1;          b = a + 1;\n  c = 999;            return b;\n  return b;","o":["인라이닝, 강도 감소","루프 언롤링, 명령어 스케줄링","레지스터 할당, 스필","상수 접기, 죽은 코드 제거"],"a":3},{"t":"choice","k":"cmp-opt-ir5","q":"SSA(정적 단일 배정) 형태의 특징으로 옳은 것은?","ex":"SSA에서는 재대입 대신 x1, x2 같은 새 이름을 만들기 때문에 어떤 사용이 어떤 정의에서 왔는지 한눈에 드러난다. 제어 흐름이 합류하는 지점에서는 phi 함수로 여러 정의를 합치며, 이 성질 덕분에 상수 전파나 DCE 같은 분석이 훨씬 간단해진다.","o":["각 변수에 값이 정확히 한 번만 배정되어 정의-사용 관계가 명확해지고 데이터 흐름 분석이 쉬워진다","모든 변수를 전역 변수로 바꿔 스코프를 없앤다","소스 코드의 주석을 IR에 그대로 보존한다","레지스터를 항상 하나만 사용하도록 강제한다"],"a":0},{"t":"input","k":"cmp-opt-ir6","q":"동일한 계산을 두 번 하는 대신 첫 결과를 재사용하는 최적화의 한국어 이름은? (예: OO OOO 제거)","ex":"공통 부분식 제거(CSE)는 같은 피연산자로 같은 연산을 반복하는 곳을 찾아 앞서 계산한 값을 다시 쓴다. 다만 그 사이에 피연산자가 변경되지 않았다는 것이 보장되어야 의미가 보존된다.","a":["공통 부분식 제거"]}],"th":{"sum":"앞단이 만든 AST는 중간 표현(IR)으로 낮아진 뒤 의미를 보존하는 최적화를 거쳐 기계어로 내려간다. 같은 언어라도 인터프리터, AOT 컴파일, JIT 중 어떤 방식으로 실행하느냐에 따라 성능 특성이 달라진다.","body":[{"h":"IR과 최적화","t":"IR은 소스 언어와 대상 기계 사이에 놓인 중간 언어로, 3-주소 코드처럼 단순한 형태를 쓴다. 여러 언어와 여러 CPU를 조합할 때 각 조합마다 컴파일러를 만들지 않아도 되게 해 주고, 최적화 패스가 공유할 공통 기반이 된다. SSA(정적 단일 배정) 형태는 각 변수에 값이 딱 한 번만 배정되도록 만들어 정의-사용 관계를 명확히 하고 데이터 흐름 분석을 쉽게 한다. 최적화는 반드시 관찰 가능한 의미를 보존해야 하며, 상수 접기, 공통 부분식 제거(CSE), 죽은 코드 제거(DCE), 인라이닝, 루프 불변 코드 이동(LICM), 강도 감소가 대표적이다."},{"h":"코드 생성과 레지스터 할당","t":"코드 생성은 크게 명령어 선택, 레지스터 할당, 명령어 스케줄링으로 나뉜다. 명령어 선택은 IR 연산을 대상 CPU의 실제 명령어로 대응시키고, 레지스터 할당은 무제한처럼 다루던 가상 레지스터를 물리 레지스터의 유한한 개수에 밀어 넣는다. 이 문제는 동시에 살아 있는 값끼리 간선을 잇는 간섭 그래프의 그래프 색칠로 모델링되며, 색이 모자라면 일부 값을 메모리로 밀어내는 스필(spill)이 발생해 메모리 접근 비용이 생긴다. 명령어 스케줄링은 파이프라인 지연을 줄이도록 순서를 재배치한다."},{"h":"인터프리터, AOT, JIT","t":"인터프리터는 소스나 바이트코드를 읽어 즉시 실행하므로 시작이 빠르고 디버깅과 반복 개발이 편하지만, 실행 중 해석 오버헤드가 있다. AOT 컴파일은 미리 기계어를 만들어 두어 실행이 빠른 대신 별도의 빌드 단계가 필요하다. 바이트코드 VM은 그 중간 형태다. JIT은 런타임에 자주 실행되는 핫 경로를 찾아 기계어로 컴파일하며, 실제로 흘러온 타입 같은 런타임 정보를 이용한 추측 최적화를 한다. 가정이 깨지면 역최적화(deoptimization)로 인터프리터로 되돌아가며, 컴파일 자체에 드는 워밍업 비용이 있어 짧게 끝나는 프로그램에서는 이득이 적을 수 있다."}],"code":{"c":"원본 IR (3-주소 코드)\n  t1 = 2 * 3\n  t2 = a + t1\n  t3 = a + t1      ; t2와 같은 계산\n  t4 = t2 + t3\n  t5 = 99          ; 아무도 안 씀\n  return t4\n\n상수 접기 -> t1 = 6\nCSE       -> t3 삭제, t3 자리에 t2 사용\nDCE       -> t5 삭제\n\n최적화 후\n  t1 = 6\n  t2 = a + t1\n  t4 = t2 + t2\n  return t4","cap":"상수 접기·CSE·DCE를 차례로 적용해도 반환값의 의미는 그대로다."},"key":["IR은 여러 언어와 여러 대상 CPU를 잇는 공통 기반이고 SSA는 흐름 분석을 돕는다","최적화는 관찰 가능한 의미를 보존하며 더 빠르거나 작은 코드를 만든다","JIT은 런타임 정보를 활용한 추측 최적화와 역최적화를 하며 워밍업 비용이 있다"]}},{"t":"코드 생성과 레지스터 할당","q":[{"t":"choice","k":"cmp-gen-reg1","q":"코드 생성 단계의 주요 하위 작업을 올바르게 묶은 것은?","ex":"코드 생성은 IR 연산을 실제 CPU 명령으로 고르고(명령어 선택), 값을 물리 레지스터에 배치하고(레지스터 할당), 파이프라인 효율을 위해 순서를 조정한다(스케줄링). 나머지 보기는 앞단 또는 컴파일러 바깥의 작업이다.","o":["토큰화, 파싱, 타입 검사","명령어 선택, 레지스터 할당, 명령어 스케줄링","심볼 테이블 구축, 스코프 해석, 타입 추론","링킹, 로딩, 가비지 컬렉션"],"a":1},{"t":"choice","k":"cmp-gen-reg2","q":"레지스터 할당을 그래프 색칠 문제로 모델링할 때, 간섭 그래프의 간선이 뜻하는 것은?","ex":"간섭 그래프의 정점은 값(가상 레지스터)이고, 생존 구간이 겹쳐 동시에 살아 있는 두 값 사이에 간선을 긋는다. 인접한 정점을 다른 색으로 칠하는 것이 곧 겹치는 값에 서로 다른 레지스터를 주는 것이며, 색의 개수가 물리 레지스터 개수에 해당한다.","o":["두 값이 같은 함수 안에 선언되었다","두 값의 타입이 같다","두 값이 동시에 살아 있어 같은 레지스터를 쓸 수 없다","두 값이 항상 함께 계산된다"],"a":2},{"t":"choice","k":"cmp-gen-reg3","q":"스필(spill)이 발생하는 상황과 그 결과로 옳은 것은?","ex":"동시에 살아 있는 값의 수가 물리 레지스터 수를 넘으면 일부를 스택 메모리로 밀어내야 하고, 이후 사용할 때마다 load/store가 추가된다. 레지스터 접근보다 메모리 접근이 훨씬 느리므로 좋은 할당기는 스필을 최소화하거나 반복 횟수가 적은 곳에서 스필하도록 고른다.","o":["물리 레지스터가 부족해 일부 값을 메모리에 저장했다가 다시 읽어 오며, 메모리 접근 비용이 늘어난다","레지스터가 남아돌아 값을 여러 레지스터에 복제하며, 성능이 향상된다","IR이 너무 커서 컴파일이 중단된다","타입 검사가 실패해 오류가 보고된다"],"a":0},{"t":"input","k":"cmp-gen-reg4","q":"다음 IR에서 세 값 a, b, c 중 서로 생존 구간이 전혀 겹치지 않아 같은 레지스터를 재사용할 수 있는 값은 총 몇 개의 물리 레지스터로 충분한가? (숫자로)","ex":"각 값은 정의된 직후 한 번 쓰이고 바로 죽으므로 어느 두 값도 동시에 살아 있지 않다. 간섭 그래프에 간선이 하나도 없어 색 하나, 즉 물리 레지스터 하나로 세 값을 모두 처리할 수 있다.","code":"a = 1\nuse(a)      ; 이후 a는 죽음\nb = 2\nuse(b)      ; 이후 b는 죽음\nc = 3\nuse(c)","a":["1"]},{"t":"choice","k":"cmp-gen-reg5","q":"명령어 스케줄링의 목적으로 가장 적절한 것은?","ex":"메모리 로드처럼 결과가 늦게 나오는 명령 뒤에 그 결과를 바로 쓰는 명령이 오면 CPU가 멈춰 기다린다. 스케줄러는 그 사이에 독립적인 명령을 끼워 넣어 대기 시간을 메우며, 물론 데이터 의존 관계를 어기지 않는 범위에서만 순서를 바꾼다.","o":["명령어 개수를 절반으로 줄이는 것","파이프라인 지연이나 메모리 대기 시간을 줄이도록 명령 순서를 재배치하는 것","소스 코드의 줄 순서를 그대로 유지하는 것","레지스터를 모두 스필시켜 메모리만 쓰게 하는 것"],"a":1}],"th":{"sum":"앞단이 만든 AST는 중간 표현(IR)으로 낮아진 뒤 의미를 보존하는 최적화를 거쳐 기계어로 내려간다. 같은 언어라도 인터프리터, AOT 컴파일, JIT 중 어떤 방식으로 실행하느냐에 따라 성능 특성이 달라진다.","body":[{"h":"IR과 최적화","t":"IR은 소스 언어와 대상 기계 사이에 놓인 중간 언어로, 3-주소 코드처럼 단순한 형태를 쓴다. 여러 언어와 여러 CPU를 조합할 때 각 조합마다 컴파일러를 만들지 않아도 되게 해 주고, 최적화 패스가 공유할 공통 기반이 된다. SSA(정적 단일 배정) 형태는 각 변수에 값이 딱 한 번만 배정되도록 만들어 정의-사용 관계를 명확히 하고 데이터 흐름 분석을 쉽게 한다. 최적화는 반드시 관찰 가능한 의미를 보존해야 하며, 상수 접기, 공통 부분식 제거(CSE), 죽은 코드 제거(DCE), 인라이닝, 루프 불변 코드 이동(LICM), 강도 감소가 대표적이다."},{"h":"코드 생성과 레지스터 할당","t":"코드 생성은 크게 명령어 선택, 레지스터 할당, 명령어 스케줄링으로 나뉜다. 명령어 선택은 IR 연산을 대상 CPU의 실제 명령어로 대응시키고, 레지스터 할당은 무제한처럼 다루던 가상 레지스터를 물리 레지스터의 유한한 개수에 밀어 넣는다. 이 문제는 동시에 살아 있는 값끼리 간선을 잇는 간섭 그래프의 그래프 색칠로 모델링되며, 색이 모자라면 일부 값을 메모리로 밀어내는 스필(spill)이 발생해 메모리 접근 비용이 생긴다. 명령어 스케줄링은 파이프라인 지연을 줄이도록 순서를 재배치한다."},{"h":"인터프리터, AOT, JIT","t":"인터프리터는 소스나 바이트코드를 읽어 즉시 실행하므로 시작이 빠르고 디버깅과 반복 개발이 편하지만, 실행 중 해석 오버헤드가 있다. AOT 컴파일은 미리 기계어를 만들어 두어 실행이 빠른 대신 별도의 빌드 단계가 필요하다. 바이트코드 VM은 그 중간 형태다. JIT은 런타임에 자주 실행되는 핫 경로를 찾아 기계어로 컴파일하며, 실제로 흘러온 타입 같은 런타임 정보를 이용한 추측 최적화를 한다. 가정이 깨지면 역최적화(deoptimization)로 인터프리터로 되돌아가며, 컴파일 자체에 드는 워밍업 비용이 있어 짧게 끝나는 프로그램에서는 이득이 적을 수 있다."}],"code":{"c":"원본 IR (3-주소 코드)\n  t1 = 2 * 3\n  t2 = a + t1\n  t3 = a + t1      ; t2와 같은 계산\n  t4 = t2 + t3\n  t5 = 99          ; 아무도 안 씀\n  return t4\n\n상수 접기 -> t1 = 6\nCSE       -> t3 삭제, t3 자리에 t2 사용\nDCE       -> t5 삭제\n\n최적화 후\n  t1 = 6\n  t2 = a + t1\n  t4 = t2 + t2\n  return t4","cap":"상수 접기·CSE·DCE를 차례로 적용해도 반환값의 의미는 그대로다."},"key":["IR은 여러 언어와 여러 대상 CPU를 잇는 공통 기반이고 SSA는 흐름 분석을 돕는다","최적화는 관찰 가능한 의미를 보존하며 더 빠르거나 작은 코드를 만든다","JIT은 런타임 정보를 활용한 추측 최적화와 역최적화를 하며 워밍업 비용이 있다"]}},{"t":"인터프리터 vs 컴파일 vs JIT","q":[{"t":"input","k":"cmp-run-jit5","q":"JIT이 핫 경로를 식별하고 컴파일하기까지 최고 성능에 도달하지 못하는 초기 구간을 가리키는 용어는? (한국어로, 예: OO 비용/시간의 앞 두 글자)","ex":"실행 초반에는 아직 프로파일 정보가 부족하고 컴파일도 끝나지 않아 인터프리터 속도로 동작하는데, 이 구간을 워밍업이라 한다. 그래서 짧게 끝나는 프로그램은 JIT의 이득을 충분히 누리지 못하고, 벤치마크에서도 워밍업 구간을 제외하고 측정하는 것이 일반적이다.","a":["워밍업"]},{"t":"choice","k":"cmp-run-jit6","q":"바이트코드 VM 방식(예: 소스를 바이트코드로 컴파일한 뒤 VM이 실행)의 위치로 가장 적절한 설명은?","ex":"바이트코드 VM은 소스를 한 번만 파싱해 조밀한 명령 형태로 바꿔 두므로 매번 소스를 해석하는 것보다 빠르고, 기계어에 종속되지 않아 이식성이 좋다. 여기에 JIT을 얹어 뜨거운 바이트코드만 기계어로 승격시키는 구조가 현대 런타임에서 흔하다.","o":["AOT 기계어 컴파일과 완전히 동일한 방식이다","소스를 한 줄씩 다시 파싱하며 실행하므로 순수 인터프리터보다 느리다","미리 한 번 컴파일해 파싱 비용을 없애되 실행은 VM이 담당하는 중간 형태다","타입 검사를 아예 수행하지 않는다는 점에서 다른 방식과 구분된다"],"a":2}],"th":{"sum":"앞단이 만든 AST는 중간 표현(IR)으로 낮아진 뒤 의미를 보존하는 최적화를 거쳐 기계어로 내려간다. 같은 언어라도 인터프리터, AOT 컴파일, JIT 중 어떤 방식으로 실행하느냐에 따라 성능 특성이 달라진다.","body":[{"h":"IR과 최적화","t":"IR은 소스 언어와 대상 기계 사이에 놓인 중간 언어로, 3-주소 코드처럼 단순한 형태를 쓴다. 여러 언어와 여러 CPU를 조합할 때 각 조합마다 컴파일러를 만들지 않아도 되게 해 주고, 최적화 패스가 공유할 공통 기반이 된다. SSA(정적 단일 배정) 형태는 각 변수에 값이 딱 한 번만 배정되도록 만들어 정의-사용 관계를 명확히 하고 데이터 흐름 분석을 쉽게 한다. 최적화는 반드시 관찰 가능한 의미를 보존해야 하며, 상수 접기, 공통 부분식 제거(CSE), 죽은 코드 제거(DCE), 인라이닝, 루프 불변 코드 이동(LICM), 강도 감소가 대표적이다."},{"h":"코드 생성과 레지스터 할당","t":"코드 생성은 크게 명령어 선택, 레지스터 할당, 명령어 스케줄링으로 나뉜다. 명령어 선택은 IR 연산을 대상 CPU의 실제 명령어로 대응시키고, 레지스터 할당은 무제한처럼 다루던 가상 레지스터를 물리 레지스터의 유한한 개수에 밀어 넣는다. 이 문제는 동시에 살아 있는 값끼리 간선을 잇는 간섭 그래프의 그래프 색칠로 모델링되며, 색이 모자라면 일부 값을 메모리로 밀어내는 스필(spill)이 발생해 메모리 접근 비용이 생긴다. 명령어 스케줄링은 파이프라인 지연을 줄이도록 순서를 재배치한다."},{"h":"인터프리터, AOT, JIT","t":"인터프리터는 소스나 바이트코드를 읽어 즉시 실행하므로 시작이 빠르고 디버깅과 반복 개발이 편하지만, 실행 중 해석 오버헤드가 있다. AOT 컴파일은 미리 기계어를 만들어 두어 실행이 빠른 대신 별도의 빌드 단계가 필요하다. 바이트코드 VM은 그 중간 형태다. JIT은 런타임에 자주 실행되는 핫 경로를 찾아 기계어로 컴파일하며, 실제로 흘러온 타입 같은 런타임 정보를 이용한 추측 최적화를 한다. 가정이 깨지면 역최적화(deoptimization)로 인터프리터로 되돌아가며, 컴파일 자체에 드는 워밍업 비용이 있어 짧게 끝나는 프로그램에서는 이득이 적을 수 있다."}],"code":{"c":"원본 IR (3-주소 코드)\n  t1 = 2 * 3\n  t2 = a + t1\n  t3 = a + t1      ; t2와 같은 계산\n  t4 = t2 + t3\n  t5 = 99          ; 아무도 안 씀\n  return t4\n\n상수 접기 -> t1 = 6\nCSE       -> t3 삭제, t3 자리에 t2 사용\nDCE       -> t5 삭제\n\n최적화 후\n  t1 = 6\n  t2 = a + t1\n  t4 = t2 + t2\n  return t4","cap":"상수 접기·CSE·DCE를 차례로 적용해도 반환값의 의미는 그대로다."},"key":["IR은 여러 언어와 여러 대상 CPU를 잇는 공통 기반이고 SSA는 흐름 분석을 돕는다","최적화는 관찰 가능한 의미를 보존하며 더 빠르거나 작은 코드를 만든다","JIT은 런타임 정보를 활용한 추측 최적화와 역최적화를 하며 워밍업 비용이 있다"]}}]},{"t":"시뮬레이션 · 눈으로 보는 코드","l":[{"t":"시뮬레이션 I","q":[{"t":"sim","k":"알고리즘 시각화","lv":2,"q":"토크나이저를 만드세요. 숫자·연산자·괄호를 토큰으로 쪼갭니다. <b>토큰을 하나 낼 때마다</b> <code>snap(\"토큰 \"+t, {지금까지:[...out], 위치:i})</code> 를 부르세요. 반환값은 토큰 배열입니다.","src":"function tokenize(src) {\n  const out = [];\n  let i = 0;\n  // 여기에 구현하세요 — 공백은 건너뛰고, 숫자는 여러 자리를 한 토큰으로\n  return out;\n}\n\nRESULT = tokenize('12 + 3*(45-6)');","tests":[{"d":"토큰이 맞게 쪼개진다","js":"JSON.stringify(RESULT)==='[\"12\",\"+\",\"3\",\"*\",\"(\",\"45\",\"-\",\"6\",\")\"]'"},{"d":"여러 자리 숫자가 한 토큰이다","js":"RESULT.indexOf('12')>=0 && RESULT.indexOf('45')>=0"},{"d":"토큰마다 장면이 남았다","js":"FRAMES.length===9"},{"d":"위치는 계속 앞으로만 간다","js":"(function(){for(var i=1;i<FRAMES.length;i++) if(FRAMES[i].value['위치']<=FRAMES[i-1].value['위치']) return false; return true;})()"},{"d":"토큰 목록이 한 개씩 자란다","js":"(function(){for(var i=0;i<FRAMES.length;i++) if(FRAMES[i].value['지금까지'].length!==i+1) return false; return true;})()"}],"ex":"렉서의 핵심은 '<b>최대한 길게 먹는다</b>'(maximal munch) 입니다. <code>12</code> 를 <code>1</code>·<code>2</code> 로 쪼개지 않고 숫자가 이어지는 동안 계속 먹습니다. 이 규칙이 있어야 <code>&gt;=</code> 가 <code>&gt;</code> 와 <code>=</code> 로 갈라지지 않습니다. 공백을 그냥 건너뛰는 것도 여기서 정해지고, 그래서 대부분의 언어에서 공백이 의미를 갖지 않습니다."},{"t":"sim","k":"자료구조 시각화","lv":3,"q":"연산자 우선순위를 스택으로 처리해 <b>후위 표기</b>로 바꾸세요(shunting-yard). <b>스택이 바뀔 때마다</b> <code>snap(라벨, {출력:[...out], 스택:[...ops]})</code> 을 부르세요. 반환값은 후위 표기 배열입니다.","src":"const PREC = { '+': 1, '-': 1, '*': 2, '/': 2 };\n\nfunction toPostfix(tokens) {\n  const out = [], ops = [];\n  // 여기에 구현하세요 — 우선순위가 높거나 같은 연산자는 먼저 꺼냅니다\n  return out;\n}\n\nRESULT = toPostfix(['1','+','2','*','3','-','4']);","tests":[{"d":"후위 표기가 맞다","js":"JSON.stringify(RESULT)==='[\"1\",\"2\",\"3\",\"*\",\"+\",\"4\",\"-\"]'"},{"d":"곱셈이 덧셈보다 먼저 나온다","js":"RESULT.indexOf('*')<RESULT.indexOf('+')"},{"d":"장면이 8개 기록됐다","js":"FRAMES.length===8"},{"d":"마지막에 스택이 비어 있다","js":"FRAMES[FRAMES.length-1].value['스택'].length===0"},{"d":"스택에는 연산자만 쌓인다","js":"FRAMES.every(f=>f.value['스택'].every(x=>['+','-','*','/'].indexOf(x)>=0))"}],"ex":"우선순위는 문법이 아니라 <b>스택을 언제 비우는가</b>로 표현됩니다. 새 연산자가 올 때 스택 위의 것이 <b>더 세거나 같으면</b> 먼저 꺼내 출력합니다 — 이 한 줄이 곱셈을 덧셈보다 먼저 계산되게 만듭니다. 같은 우선순위에서 꺼내는 것이 <b>왼쪽 결합</b>이고, 거듭제곱처럼 오른쪽 결합인 연산자는 부등호를 <code>&gt;</code> 로 바꿔야 합니다."},{"t":"sim","k":"상태 시각화","lv":3,"q":"심볼 테이블의 <b>스코프</b>를 만드세요. 블록에 들어가면 새 스코프를 쌓고 나오면 걷습니다. 이름을 찾을 때는 <b>안쪽부터</b> 봅니다. <b>연산마다</b> <code>snap(라벨, {스코프:scopes.map(s=&gt;Object.keys(s)), 찾은값:v})</code> 를 부르세요. 반환값은 조회 결과 배열입니다.","src":"function scopes(ops) {\n  const stack = [{}], found = [];\n  // 여기에 구현하세요 — ['push'], ['pop'], ['def', 이름, 값], ['get', 이름]\n  return found;\n}\n\nRESULT = scopes([['def','x',1],['push'],['def','x',2],['get','x'],['pop'],['get','x'],['get','y']]);","tests":[{"d":"안쪽 스코프가 바깥을 가린다","js":"RESULT[0]===2"},{"d":"블록을 나오면 바깥 값이 다시 보인다","js":"RESULT[1]===1"},{"d":"없는 이름은 null 이다","js":"RESULT[2]===null"},{"d":"연산마다 장면이 남았다","js":"FRAMES.length===7"},{"d":"스코프 깊이가 1 아래로 내려가지 않는다","js":"FRAMES.every(f=>f.value['스코프'].length>=1)"}],"ex":"이름 해석(name resolution)은 <b>안쪽 스코프부터 바깥으로</b> 올라가며 찾는 것뿐입니다. 안쪽에 같은 이름이 있으면 바깥이 <b>가려집니다</b>(shadowing) — 버그가 아니라 규칙입니다. 블록을 나오면 그 스코프가 통째로 사라지므로 안에서 선언한 이름은 밖에서 보이지 않습니다. 클로저는 이 '사라져야 할 스코프' 를 함수가 붙잡고 있는 것이라, 컴파일러는 그런 변수를 힙에 올립니다."},{"t":"sim","k":"알고리즘 시각화","lv":3,"q":"후위 표기식을 <b>스택으로 계산</b>하세요. <b>스택이 바뀔 때마다</b> <code>snap(라벨, [...stack])</code> 을 부르세요. 반환값은 계산 결과입니다.","src":"function evalPostfix(tokens) {\n  const stack = [];\n  // 여기에 구현하세요 — 숫자는 쌓고, 연산자는 둘을 꺼내 계산해 다시 쌓습니다\n  return stack[0];\n}\n\nRESULT = evalPostfix(['1','2','3','*','+','4','-']);","tests":[{"d":"계산 결과가 3 이다","js":"RESULT===3"},{"d":"토큰마다 장면이 남았다","js":"FRAMES.length===7"},{"d":"마지막에 값이 하나만 남는다","js":"FRAMES[FRAMES.length-1].value.length===1"},{"d":"연산할 때마다 스택이 하나 줄어든다","js":"(function(){var f=FRAMES.filter(x=>/계산/.test(x.label));return f.length===3;})()"},{"d":"뺄셈의 피연산자 순서가 맞다 (a - b)","js":"(function(){var f=FRAMES.filter(x=>/계산/.test(x.label));return /7-4/.test(f[2].label);})()"}],"ex":"후위 표기에는 괄호가 없습니다 — 순서가 이미 <b>토큰 배치에 들어 있기</b> 때문입니다. 그래서 계산기는 스택 하나로 끝납니다. 주의할 곳은 꺼내는 순서입니다: 먼저 꺼낸 것이 <b>오른쪽</b> 피연산자라 <code>a - b</code> 로 써야 합니다. 뒤집으면 덧셈·곱셈은 맞고 뺄셈·나눗셈만 틀리는, 찾기 어려운 버그가 됩니다."}],"th":{"sum":"코드를 쓰고 무슨 일이 일어나는지 눈으로 확인하는 훈련입니다. snap(라벨, 값) 을 부르면 그 순간이 한 장면으로 남고, 슬라이더로 되감아 볼 수 있습니다.","body":[{"h":"설명 대신 장면으로 이해한다","t":"'버블 정렬은 O(n²)' 이라는 문장보다, 교환 장면이 <b>몇 개나 쌓이는지</b> 보는 편이 빠릅니다. 이진 탐색에서 흐릿해지는 칸이 절반씩 늘어나는 것도 마찬가지입니다."},{"h":"기록은 사본으로 남긴다","t":"<code>snap(\"단계\", arr)</code> 는 그 순간의 값을 복사해 둡니다. 배열을 그대로 넘겨도 되지만, 스택처럼 계속 바뀌는 것은 <code>[...stack]</code> 으로 넘겨야 나중에 뒤섞이지 않습니다."},{"h":"강조로 '지금 보는 곳' 을 표시한다","t":"세 번째 인자로 <code>{hi:[i,j]}</code> 를 주면 그 칸이 빨갛게, <code>{dim:[...]}</code> 를 주면 흐리게 그려집니다. 알고리즘이 <b>어디를 보고 있는지</b>가 드러납니다."},{"h":"채점은 결과 + 흐름","t":"반환값만 맞추면 되는 게 아니라 <b>장면의 흐름</b>도 봅니다 — 창이 한 칸씩 움직였는가, 메모 표가 한 칸씩 커졌는가. 우연히 맞은 답과 제대로 만든 답이 갈립니다."}],"code":{"t":"한 줄이면 장면이 남는다","c":"if (a[j] > a[j+1]) {\n  [a[j], a[j+1]] = [a[j+1], a[j]];\n  snap(\"교환\", a, { hi: [j, j+1] });   // ← 이 순간이 기록된다\n}"},"key":["snap(라벨, 값, 옵션) 으로 순간을 남긴다","계속 바뀌는 값은 사본으로 넘긴다","hi·dim 으로 보고 있는 위치를 표시한다","채점은 결과값과 장면의 흐름을 함께 본다"]}},{"t":"시뮬레이션 II","q":[{"t":"sim","k":"메모리 시각화","lv":2,"q":"상수 접기(constant folding)를 하세요. 트리에서 <b>양쪽이 모두 숫자인 노드</b>를 계산해 하나로 접습니다. <b>접을 때마다</b> <code>snap(\"접기 \"+식, {남은노드:n})</code> 을 부르세요. 반환값은 접힌 결과입니다.","src":"const TREE = { op:'+', l:{ op:'*', l:{n:2}, r:{n:3} }, r:{ op:'-', l:{n:10}, r:{n:4} } };\n\nfunction fold(node) {\n  // 여기에 구현하세요 — 재귀로 내려가며 숫자끼리 만나면 계산합니다\n  return node;\n}\n\nRESULT = fold(TREE).n;","tests":[{"d":"전부 접혀 12 가 된다","js":"RESULT===12"},{"d":"접기가 3번 일어난다","js":"FRAMES.length===3"},{"d":"안쪽부터 접힌다 (곱셈이 먼저)","js":"/2\\*3/.test(FRAMES[0].label)"},{"d":"남은 노드 수가 계속 줄어든다","js":"(function(){for(var i=1;i<FRAMES.length;i++) if(FRAMES[i].value['남은노드']>=FRAMES[i-1].value['남은노드']) return false; return true;})()"},{"d":"마지막 접기가 덧셈이다","js":"/\\+/.test(FRAMES[2].label)"}],"ex":"상수 접기는 컴파일러 최적화의 가장 기본입니다. <code>2 * 3</code> 을 실행 시점에 계산할 이유가 없으므로 <b>컴파일 때 6으로 바꿔</b>버립니다. 반드시 <b>잎에서부터</b> 접어야 안쪽 결과가 바깥 계산에 쓰입니다 — 위에서부터 보면 양쪽이 아직 숫자가 아니라 아무것도 못 접습니다. 부동소수에서는 이 최적화가 결과를 미세하게 바꿀 수 있어, 엄격한 모드에서는 끄기도 합니다."}],"th":{"sum":"코드를 쓰고 무슨 일이 일어나는지 눈으로 확인하는 훈련입니다. snap(라벨, 값) 을 부르면 그 순간이 한 장면으로 남고, 슬라이더로 되감아 볼 수 있습니다.","body":[{"h":"설명 대신 장면으로 이해한다","t":"'버블 정렬은 O(n²)' 이라는 문장보다, 교환 장면이 <b>몇 개나 쌓이는지</b> 보는 편이 빠릅니다. 이진 탐색에서 흐릿해지는 칸이 절반씩 늘어나는 것도 마찬가지입니다."},{"h":"기록은 사본으로 남긴다","t":"<code>snap(\"단계\", arr)</code> 는 그 순간의 값을 복사해 둡니다. 배열을 그대로 넘겨도 되지만, 스택처럼 계속 바뀌는 것은 <code>[...stack]</code> 으로 넘겨야 나중에 뒤섞이지 않습니다."},{"h":"강조로 '지금 보는 곳' 을 표시한다","t":"세 번째 인자로 <code>{hi:[i,j]}</code> 를 주면 그 칸이 빨갛게, <code>{dim:[...]}</code> 를 주면 흐리게 그려집니다. 알고리즘이 <b>어디를 보고 있는지</b>가 드러납니다."},{"h":"채점은 결과 + 흐름","t":"반환값만 맞추면 되는 게 아니라 <b>장면의 흐름</b>도 봅니다 — 창이 한 칸씩 움직였는가, 메모 표가 한 칸씩 커졌는가. 우연히 맞은 답과 제대로 만든 답이 갈립니다."}],"code":{"t":"한 줄이면 장면이 남는다","c":"if (a[j] > a[j+1]) {\n  [a[j], a[j+1]] = [a[j+1], a[j]];\n  snap(\"교환\", a, { hi: [j, j+1] });   // ← 이 순간이 기록된다\n}"},"key":["snap(라벨, 값, 옵션) 으로 순간을 남긴다","계속 바뀌는 값은 사본으로 넘긴다","hi·dim 으로 보고 있는 위치를 표시한다","채점은 결과값과 장면의 흐름을 함께 본다"]}},{"t":"시뮬레이션 III","q":[{"t":"sim","k":"컴파일러 시뮬레이션","lv":2,"q":"<b>토큰화</b>를 구현하세요. 산술식을 숫자·연산자·괄호로 나누고 토큰마다 <code>snap</code> 으로 기록한 뒤 <b>토큰 수</b>를 돌려주세요.","src":"const SRC = '12 + 3*(45 - 6)';\n\nfunction tokenize() {\n  const tokens = [];\n  // 여기에 구현하세요\n  return tokens.length;\n}\n\nRESULT = tokenize();","tests":[{"d":"토큰은 9개다","js":"RESULT===9"},{"d":"토큰마다 장면이 기록된다","js":"FRAMES.length===9"},{"d":"숫자 토큰이 4개다","js":"FRAMES.filter(f=>f.opt.kind==='num').length===4"},{"d":"여러 자리 숫자가 한 토큰이다","js":"FRAMES.some(f=>/num 12/.test(f.label)) && FRAMES.some(f=>/num 45/.test(f.label))"},{"d":"토큰 수가 1씩 증가한다","js":"FRAMES.every((f,i)=>f.value[0]===i+1)"}],"ex":"토큰화의 핵심은 <b>최대 길이 우선</b>입니다 — <code>12</code> 를 <code>1</code>·<code>2</code> 두 토큰으로 자르면 안 되므로, 숫자가 시작되면 <b>더 이상 숫자가 아닐 때까지</b> 읽습니다. 같은 원리가 <code>&gt;=</code> 를 <code>&gt;</code>·<code>=</code> 로 자르지 않게 하고, 공백은 <b>토큰을 나누는 역할만</b> 하고 사라집니다. 이 단계에서 이미 '이 문자는 여기 올 수 없다' 는 오류가 잡힙니다."},{"t":"sim","k":"컴파일러 시뮬레이션","lv":3,"q":"<b>연산자 우선순위</b>를 지키는 후위 표기(RPN) 변환을 구현하세요. 출력에 토큰이 추가될 때마다 <code>snap</code> 으로 기록하고 <b>최종 후위식 문자열</b>을 돌려주세요.","src":"const TOKENS = ['2', '+', '3', '*', '4'];\nconst PREC = { '+': 1, '-': 1, '*': 2, '/': 2 };\n\nfunction toRpn() {\n  const out = [], ops = [];\n  // 여기에 구현하세요 — 우선순위가 높거나 같은 연산자는 먼저 꺼냅니다\n  return out.join(' ');\n}\n\nRESULT = toRpn();","tests":[{"d":"후위식이 2 3 4 * + 다","js":"RESULT==='2 3 4 * +'"},{"d":"출력 길이가 5다","js":"RESULT.split(' ').length===5"},{"d":"곱셈이 덧셈보다 먼저 나온다","js":"RESULT.indexOf('*')<RESULT.indexOf('+')"},{"d":"스택 깊이가 음수가 되지 않는다","js":"FRAMES.every(f=>f.opt.stack>=0)"},{"d":"마지막에 스택이 비어 있다","js":"FRAMES[FRAMES.length-1].opt.stack===0"}],"ex":"후위 표기는 <b>괄호가 필요 없습니다</b> — 순서가 이미 표현에 담겨 있기 때문입니다. 변환 규칙 한 줄이 우선순위를 만듭니다: 새 연산자보다 <b>우선순위가 높거나 같은</b> 것을 먼저 꺼내면 <code>2+3*4</code> 에서 <code>*</code> 가 <code>+</code> 보다 먼저 출력됩니다. 결합 방향(오른쪽 결합인 <code>^</code>)은 '같을 때' 조건만 바꾸면 됩니다. 실제 컴파일러의 파서도 같은 원리를 씁니다."},{"t":"sim","k":"컴파일러 시뮬레이션","lv":3,"q":"<b>재귀 하강 파서</b>로 괄호 깊이를 검사하세요. 각 문자의 깊이를 <code>snap</code> 으로 기록하고, 균형이 맞으면 <b>최대 깊이</b>를, 아니면 -1 을 돌려주세요.","src":"const SRC = '((a+b)*(c-(d/e)))';\n\nfunction depth() {\n  let d = 0, max = 0;\n  // 여기에 구현하세요\n  return max;\n}\n\nRESULT = depth();","tests":[{"d":"최대 깊이는 3이다","js":"RESULT===3"},{"d":"괄호마다 장면이 기록된다","js":"FRAMES.length===8"},{"d":"깊이가 음수가 되지 않는다","js":"FRAMES.every(f=>f.value[0]>=0)"},{"d":"마지막 깊이가 0이다","js":"FRAMES[FRAMES.length-1].value[0]===0"},{"d":"최대 깊이가 줄어들지 않는다","js":"FRAMES.every((f,i)=>i===0||f.opt.max>=FRAMES[i-1].opt.max)"}],"ex":"재귀 하강 파서의 <b>재귀 깊이</b>가 곧 이 괄호 깊이입니다 — 그래서 입력이 깊이를 정하는 파서는 <b>스택 오버플로 위험</b>을 안습니다. JSON·표현식 파서에 <b>최대 깊이 제한</b>이 있는 이유이고, 없으면 40KB 짜리 입력 하나로 프로세스를 죽일 수 있습니다(실제 취약점 사례가 많습니다). 깊이 추적은 오류 메시지에 '어느 괄호가 안 닫혔는지' 를 알려 주는 데도 쓰입니다."},{"t":"sim","k":"컴파일러 시뮬레이션","lv":3,"q":"<b>상수 접기(constant folding)</b>를 구현하세요. 후위식에서 숫자끼리의 연산을 미리 계산해 접고, 접을 때마다 <code>snap</code> 으로 기록한 뒤 <b>남은 토큰 수</b>를 돌려주세요.","src":"const RPN = ['2', '3', '*', 'x', '+', '4', '5', '+', '-'];\n\nfunction fold() {\n  const st = [];\n  // 여기에 구현하세요 — 두 피연산자가 모두 숫자면 계산해서 하나로 접습니다\n  return st.length;\n}\n\nRESULT = fold();","tests":[{"d":"최종 스택에 하나만 남는다","js":"RESULT===1"},{"d":"접기가 2번 일어난다","js":"FRAMES.filter(f=>f.opt.folded).length===2"},{"d":"변수가 낀 연산은 접히지 않는다","js":"FRAMES.filter(f=>f.opt.folded===false).length===2"},{"d":"2*3 이 6으로 접힌다","js":"FRAMES.some(f=>/2\\*3=6/.test(f.label))"},{"d":"스택 크기가 음수가 되지 않는다","js":"FRAMES.every(f=>f.value[0]>=0)"}],"ex":"상수 접기는 가장 기본적인 최적화입니다 — <code>2*3</code> 은 실행 시점에 계산할 이유가 없으므로 <b>컴파일 때 6으로</b> 바꿉니다. 변수가 끼면 접을 수 없다는 점이 중요합니다(값을 모르니까). 이 최적화가 <b>다른 최적화를 열어 주기도</b> 합니다: 접은 결과가 0이면 곱셈 전체가 사라지고, 조건이 상수면 <b>죽은 코드 제거</b>로 이어집니다. 그래서 컴파일러는 최적화를 여러 번 반복합니다."}],"th":{"sum":"코드를 쓰고 무슨 일이 일어나는지 눈으로 확인하는 훈련입니다. snap(라벨, 값) 을 부르면 그 순간이 한 장면으로 남고, 슬라이더로 되감아 볼 수 있습니다.","body":[{"h":"설명 대신 장면으로 이해한다","t":"'버블 정렬은 O(n²)' 이라는 문장보다, 교환 장면이 <b>몇 개나 쌓이는지</b> 보는 편이 빠릅니다. 이진 탐색에서 흐릿해지는 칸이 절반씩 늘어나는 것도 마찬가지입니다."},{"h":"기록은 사본으로 남긴다","t":"<code>snap(\"단계\", arr)</code> 는 그 순간의 값을 복사해 둡니다. 배열을 그대로 넘겨도 되지만, 스택처럼 계속 바뀌는 것은 <code>[...stack]</code> 으로 넘겨야 나중에 뒤섞이지 않습니다."},{"h":"강조로 '지금 보는 곳' 을 표시한다","t":"세 번째 인자로 <code>{hi:[i,j]}</code> 를 주면 그 칸이 빨갛게, <code>{dim:[...]}</code> 를 주면 흐리게 그려집니다. 알고리즘이 <b>어디를 보고 있는지</b>가 드러납니다."},{"h":"채점은 결과 + 흐름","t":"반환값만 맞추면 되는 게 아니라 <b>장면의 흐름</b>도 봅니다 — 창이 한 칸씩 움직였는가, 메모 표가 한 칸씩 커졌는가. 우연히 맞은 답과 제대로 만든 답이 갈립니다."}],"code":{"t":"한 줄이면 장면이 남는다","c":"if (a[j] > a[j+1]) {\n  [a[j], a[j+1]] = [a[j+1], a[j]];\n  snap(\"교환\", a, { hi: [j, j+1] });   // ← 이 순간이 기록된다\n}"},"key":["snap(라벨, 값, 옵션) 으로 순간을 남긴다","계속 바뀌는 값은 사본으로 넘긴다","hi·dim 으로 보고 있는 위치를 표시한다","채점은 결과값과 장면의 흐름을 함께 본다"]}},{"t":"시뮬레이션 IV","q":[{"t":"sim","k":"컴파일러 시뮬레이션","lv":4,"q":"<b>죽은 코드 제거</b>를 구현하세요. 각 문장이 결과에 영향을 주는지 역방향으로 판정하고, 제거되는 문장 수를 돌려주세요.","src":"const STMTS = [\n  {id:0, def:'a', uses:[]},\n  {id:1, def:'b', uses:['a']},\n  {id:2, def:'c', uses:['a']},\n  {id:3, def:'d', uses:['c']},\n  {id:4, def:'ret', uses:['b']}\n];\nconst LIVE_OUT = ['ret'];\n\nfunction dce() {\n  return 0;\n}\n\nRESULT = dce();","tests":[{"d":"제거되는 문장은 2개다","js":"RESULT===2"},{"d":"문장마다 장면이 기록된다","js":"FRAMES.length===5"},{"d":"역방향으로 훑는다 (첫 장면이 마지막 문장)","js":"/ret/.test(FRAMES[0].label)"},{"d":"살아 있는 변수 집합이 줄어들지 않는다","js":"FRAMES.every((f,i)=>i===0||f.opt.live.length>=FRAMES[i-1].opt.live.length)"},{"d":"유지된 문장 수가 줄어들지 않는다","js":"FRAMES.every((f,i)=>i===0||f.value[0]>=FRAMES[i-1].value[0])"}],"ex":"죽은 코드 제거는 <b>뒤에서 앞으로</b> 훑습니다 — 무엇이 필요한지는 <b>나중에 쓰이는지</b>로 정해지기 때문입니다. 반환값에서 시작해 '이 값을 만들려면 무엇이 필요한가' 를 거슬러 올라가면, 아무도 안 쓰는 <code>c</code>·<code>d</code> 가 자연스럽게 떨어져 나갑니다. 같은 <b>역방향 데이터 흐름 분석</b>이 레지스터 할당과 미사용 변수 경고에도 쓰입니다."},{"t":"sim","k":"컴파일러 시뮬레이션","lv":2,"q":"<b>심볼 테이블과 스코프</b>를 모델링하세요. 블록이 열리고 닫힐 때마다 스코프를 쌓고, 각 참조가 <b>어느 스코프에서 해결되는지</b> 기록한 뒤 <b>해결 실패 수</b>를 돌려주세요.","src":"const EVENTS = [\n  {op:'declare', name:'x'},\n  {op:'open'},\n  {op:'declare', name:'y'},\n  {op:'ref', name:'x'},\n  {op:'ref', name:'y'},\n  {op:'close'},\n  {op:'ref', name:'y'}\n];\n\nfunction scopes() {\n  let unresolved = 0;\n  // 여기에 구현하세요 — 안쪽 스코프부터 바깥으로 찾습니다\n  return unresolved;\n}\n\nRESULT = scopes();","tests":[{"d":"해결 실패는 1건이다","js":"RESULT===1"},{"d":"이벤트마다 장면이 기록된다","js":"FRAMES.length===7"},{"d":"바깥 변수 x 는 안쪽에서 보인다","js":"FRAMES.some(f=>/참조 x → 깊이 0/.test(f.label))"},{"d":"블록이 닫히면 안쪽 변수는 사라진다","js":"FRAMES[6].opt.found===-1"},{"d":"스코프 깊이가 1 아래로 내려가지 않는다","js":"FRAMES.every(f=>f.opt.depth>=1)"}],"ex":"이름 해결은 <b>안쪽에서 바깥으로</b> 찾습니다 — 그래서 안쪽에 같은 이름이 있으면 바깥 것을 가립니다(섀도잉). 블록이 닫히면 그 스코프의 이름은 사라지므로, 밖에서 참조하면 <b>컴파일 오류</b>가 납니다. 자바스크립트의 <code>var</code> 가 헷갈리는 이유가 여기에 있습니다 — 블록 스코프가 아니라 함수 스코프라 이 모델과 다르게 동작합니다."},{"t":"sim","k":"컴파일러 시뮬레이션","lv":3,"q":"<b>타입 검사</b>를 구현하세요. 각 연산의 피연산자 타입을 확인해 결과 타입을 정하고, 불일치를 <code>snap</code> 으로 기록한 뒤 <b>타입 오류 수</b>를 돌려주세요.","src":"const OPS = [\n  {op:'+', l:'int', r:'int'},\n  {op:'+', l:'int', r:'string'},\n  {op:'<', l:'int', r:'int'},\n  {op:'&&', l:'bool', r:'bool'},\n  {op:'&&', l:'int', r:'bool'}\n];\n\nfunction typecheck() {\n  let errors = 0;\n  // 여기에 구현하세요 — 산술은 int+int, 비교는 int→bool, 논리는 bool+bool\n  return errors;\n}\n\nRESULT = typecheck();","tests":[{"d":"타입 오류는 2건이다","js":"RESULT===2"},{"d":"연산마다 장면이 기록된다","js":"FRAMES.length===5"},{"d":"비교 연산의 결과 타입은 bool 이다","js":"FRAMES[2].opt.result==='bool'"},{"d":"정수 덧셈의 결과 타입은 int 다","js":"FRAMES[0].opt.result==='int'"},{"d":"오류 수가 줄어들지 않는다","js":"FRAMES.every((f,i)=>i===0||f.value[0]>=FRAMES[i-1].value[0])"}],"ex":"타입 검사는 <b>연산마다 규칙을 적용해 결과 타입을 계산</b>하는 과정입니다. 비교 연산이 <code>bool</code> 을 돌려준다는 점이 중요합니다 — 그래야 <code>a &lt; b &amp;&amp; c</code> 같은 식을 검사할 수 있습니다. 오류가 나면 그 자리에 <b>error 타입</b>을 넣고 계속 진행하는 것이 요령입니다: 그래야 <b>한 번에 여러 오류</b>를 보고할 수 있습니다(첫 오류에서 멈추면 고치고 다시 컴파일하기를 반복해야 합니다)."},{"t":"sim","k":"컴파일러 시뮬레이션","lv":4,"q":"<b>레지스터 할당</b>을 모델링하세요. 변수의 생존 구간이 주어질 때 겹치는 구간에는 다른 레지스터를 배정하고, 레지스터가 2개뿐일 때 <b>메모리로 밀려나는(spill) 변수 수</b>를 돌려주세요.","src":"const LIVE = [\n  {v:'a', from:0, to:5},\n  {v:'b', from:1, to:3},\n  {v:'c', from:2, to:7},\n  {v:'d', from:4, to:6},\n  {v:'e', from:6, to:9}\n];\nconst REGS = 2;\n\nfunction alloc() {\n  let spills = 0;\n  return spills;\n}\n\nRESULT = alloc();","tests":[{"d":"메모리로 밀려나는 변수는 1개다","js":"RESULT===1"},{"d":"변수마다 장면이 기록된다","js":"FRAMES.length===5"},{"d":"동시에 레지스터를 쓰는 변수가 2를 넘지 않는다","js":"FRAMES.every(f=>f.opt.active<=2)"},{"d":"spill 수가 줄어들지 않는다","js":"FRAMES.every((f,i)=>i===0||f.value[0]>=FRAMES[i-1].value[0])"},{"d":"레지스터 배정이 4번 일어난다","js":"FRAMES.filter(f=>/^reg/.test(f.label)).length===4"}],"ex":"레지스터 할당은 <b>그래프 색칠 문제</b>와 같습니다 — 생존 구간이 겹치는 변수는 같은 레지스터를 쓸 수 없으므로 '인접한 정점은 다른 색' 과 정확히 같은 구조입니다. 레지스터가 모자라면 일부를 <b>메모리로 밀어내는데</b>(spill), 메모리 접근은 레지스터보다 수십 배 느리므로 <b>무엇을 밀어낼지</b>가 성능을 좌우합니다. 그래서 루프 안에서 자주 쓰이는 변수는 마지막까지 레지스터에 남깁니다."}],"th":{"sum":"코드를 쓰고 무슨 일이 일어나는지 눈으로 확인하는 훈련입니다. snap(라벨, 값) 을 부르면 그 순간이 한 장면으로 남고, 슬라이더로 되감아 볼 수 있습니다.","body":[{"h":"설명 대신 장면으로 이해한다","t":"'버블 정렬은 O(n²)' 이라는 문장보다, 교환 장면이 <b>몇 개나 쌓이는지</b> 보는 편이 빠릅니다. 이진 탐색에서 흐릿해지는 칸이 절반씩 늘어나는 것도 마찬가지입니다."},{"h":"기록은 사본으로 남긴다","t":"<code>snap(\"단계\", arr)</code> 는 그 순간의 값을 복사해 둡니다. 배열을 그대로 넘겨도 되지만, 스택처럼 계속 바뀌는 것은 <code>[...stack]</code> 으로 넘겨야 나중에 뒤섞이지 않습니다."},{"h":"강조로 '지금 보는 곳' 을 표시한다","t":"세 번째 인자로 <code>{hi:[i,j]}</code> 를 주면 그 칸이 빨갛게, <code>{dim:[...]}</code> 를 주면 흐리게 그려집니다. 알고리즘이 <b>어디를 보고 있는지</b>가 드러납니다."},{"h":"채점은 결과 + 흐름","t":"반환값만 맞추면 되는 게 아니라 <b>장면의 흐름</b>도 봅니다 — 창이 한 칸씩 움직였는가, 메모 표가 한 칸씩 커졌는가. 우연히 맞은 답과 제대로 만든 답이 갈립니다."}],"code":{"t":"한 줄이면 장면이 남는다","c":"if (a[j] > a[j+1]) {\n  [a[j], a[j+1]] = [a[j+1], a[j]];\n  snap(\"교환\", a, { hi: [j, j+1] });   // ← 이 순간이 기록된다\n}"},"key":["snap(라벨, 값, 옵션) 으로 순간을 남긴다","계속 바뀌는 값은 사본으로 넘긴다","hi·dim 으로 보고 있는 위치를 표시한다","채점은 결과값과 장면의 흐름을 함께 본다"]}}]},{"t":"실행형 실전 — 미니 컴파일러를 만든다","l":[{"t":"렉서·재귀 하강·션팅 야드","xp":80,"th":{"sum":"컴파일러 앞단은 세 가지 작은 결정의 연속이다 — **가장 길게 자르고**(렉서), **계층으로 우선순위를 만들고**(파서), **스택으로 순서를 뒤집는다**(코드 생성).","body":[{"h":"자르기와 묶기","t":"렉서의 제1규칙은 최장 일치다 — == 는 = 두 개가 아니라 한 토큰이므로 **긴 것부터 검사**한다. 파서는 expr→term→factor 계층으로 우선순위를 표현하고, 좌결합은 재귀가 아니라 **반복문**으로 만든다. 10−2−3 이 5인지 11인지가 여기서 갈린다."},{"h":"후위 표기는 기계의 순서","t":"션팅 야드는 '스택 위 연산자가 나보다 세거나 **같으면** 먼저 내보낸다' 로 중위를 후위로 바꾼다. 후위 계산의 단골 버그는 pop 순서 — 먼저 pop 한 값이 **오른쪽** 피연산자다. 덧셈·곱셈은 교환법칙이 버그를 숨기고 뺄셈에서야 드러난다."}],"code":{"c":"// 먼저 pop = 오른쪽 피연산자\nconst b = st.pop(), a = st.pop();\nst.push(a - b);  // b - a 가 아니다","cap":"교환법칙 없는 연산으로 테스트해야 잡힌다"},"key":["최장 일치 — 긴 토큰을 먼저 검사","우선순위는 문법 계층, 좌결합은 반복문","'세거나 같으면 내보내기' 의 같음이 좌결합","후위 계산: 먼저 pop 이 오른쪽"]},"q":[{"t":"code","run":"js","k":"어휘 분석 — 최장 일치","cat":"internals","q":"<b>어휘 분석기(lexer)</b>를 구현하세요. <code>lex(srcText)</code> 는 소문자 식별자(<code>a-z</code> 시작, 이후 숫자 허용)·정수·연산자(<code>+ - * / = ==</code>)를 토큰으로 자릅니다. 공백은 건너뛰고, <b><code>==</code> 는 <code>=</code> 두 개가 아니라 한 토큰</b>(최장 일치)이며, 모르는 문자를 만나면 <code>null</code> 입니다.","src":"function lex(srcText) {\n  // TODO: 최장 일치로 토큰 자르기\n  return srcText.split(' ').map((w) => ({ t: 'id', v: w }));\n}","sol":"function lex(srcText) {\n  const out = [];\n  let i = 0;\n  while (i < srcText.length) {\n    const ch = srcText[i];\n    if (ch === ' ') { i++; continue; }\n    if (/[0-9]/.test(ch)) {\n      let j = i; while (j < srcText.length && /[0-9]/.test(srcText[j])) j++;\n      out.push({ t: 'num', v: Number(srcText.slice(i, j)) }); i = j; continue;\n    }\n    if (/[a-z]/.test(ch)) {\n      let j = i; while (j < srcText.length && /[a-z0-9]/.test(srcText[j])) j++;\n      out.push({ t: 'id', v: srcText.slice(i, j) }); i = j; continue;\n    }\n    if (srcText.slice(i, i + 2) === '==') { out.push({ t: 'op', v: '==' }); i += 2; continue; }\n    if ('+-*/='.includes(ch)) { out.push({ t: 'op', v: ch }); i++; continue; }\n    return null;\n  }\n  return out;\n}","tests":[{"in":"lex('ab1 = 10')","out":"[{t:'id',v:'ab1'},{t:'op',v:'='},{t:'num',v:10}]"},{"in":"lex('a==b')","out":"[{t:'id',v:'a'},{t:'op',v:'=='},{t:'id',v:'b'}]"},{"in":"lex('12+345')","out":"[{t:'num',v:12},{t:'op',v:'+'},{t:'num',v:345}]"},{"in":"lex('a $ b')","out":"null"}],"edge":[{"in":"lex('')","out":"[]"},{"in":"lex('x=1==2')","out":"[{t:'id',v:'x'},{t:'op',v:'='},{t:'num',v:1},{t:'op',v:'=='},{t:'num',v:2}]"}],"ex":"🎯 렉서의 제1규칙은 <b>최장 일치(maximal munch)</b>입니다. <code>==</code> 를 보면 <code>=</code> 두 개가 아니라 가장 긴 토큰 하나로 자릅니다 — 그래서 <b><code>==</code> 검사를 <code>=</code> 보다 먼저</b> 해야 합니다. 순서를 바꾸면 render 는 되는데 파서가 엉뚱한 곳에서 죽습니다.\n💡 숫자·식별자도 같은 원리입니다. <code>345</code> 는 '3, 4, 5' 가 아니라 한 덩어리를 <b>끝까지 읽고</b> 하나의 토큰으로 만듭니다. 렉서는 '문자를 상태에 따라 묶는' 유한 상태 기계입니다.\n⚠️ 모르는 문자를 조용히 건너뛰면 <b>오류 위치가 파서로 밀려나</b> 진단이 어려워집니다. 렉서 단계에서 즉시 실패해야 '몇 번째 글자가 문제' 라고 말할 수 있습니다.\n🔧 자바스크립트의 유명한 함정 <code>a+++b</code> 가 <code>(a++)+b</code> 로 읽히는 것도 최장 일치 때문입니다. 문법 설계는 렉서 규칙까지 고려해야 합니다."},{"t":"code","run":"js","k":"재귀 하강 파서","cat":"internals","q":"<b>재귀 하강</b>으로 수식을 계산하세요. <code>evalExpr(s)</code> 는 <code>+ - * / ( )</code> 와 정수로 된 식(공백 없음)을 계산합니다. 문법은 <code>expr → term (±term)*</code>, <code>term → factor (×÷factor)*</code>, <code>factor → 숫자 | (expr)</code> 이고, <b>같은 우선순위는 왼쪽부터</b>(<code>10-2-3 = 5</code>) 계산합니다.","src":"function evalExpr(s) {\n  // TODO: expr → term → factor\n  let acc = 0;\n  s.split(/[+]/).forEach((part) => { acc += Number(part) || 0; });\n  return acc;\n}","sol":"function evalExpr(s) {\n  let pos = 0;\n  const factor = () => {\n    if (s[pos] === '(') { pos++; const v = expr(); pos++; return v; }\n    let j = pos; while (j < s.length && /[0-9]/.test(s[j])) j++;\n    const v = Number(s.slice(pos, j)); pos = j; return v;\n  };\n  const term = () => {\n    let v = factor();\n    while (s[pos] === '*' || s[pos] === '/') { const op = s[pos++]; const w = factor(); v = op === '*' ? v * w : v / w; }\n    return v;\n  };\n  const expr = () => {\n    let v = term();\n    while (s[pos] === '+' || s[pos] === '-') { const op = s[pos++]; const w = term(); v = op === '+' ? v + w : v - w; }\n    return v;\n  };\n  return expr();\n}","tests":[{"in":"evalExpr('2+3*4')","out":"14"},{"in":"evalExpr('(2+3)*4')","out":"20"},{"in":"evalExpr('10-2-3')","out":"5"},{"in":"evalExpr('20/2/5')","out":"2"}],"edge":[{"in":"evalExpr('7')","out":"7"},{"in":"evalExpr('2*(3+4)-5')","out":"9"}],"ex":"🎯 우선순위는 <b>문법 계층</b>으로 표현됩니다. <code>expr</code> 가 <code>term</code> 을 부르고 <code>term</code> 이 <code>factor</code> 를 부르는 구조에서, <b>아래층일수록 먼저 묶입니다</b> — 그래서 <code>*</code> 가 <code>+</code> 보다 세게 결합합니다.\n💡 좌결합은 <b>재귀가 아니라 반복문</b>으로 만듭니다. <code>10-2-3</code> 을 <code>while</code> 로 왼쪽부터 누적하면 <code>(10−2)−3 = 5</code>. 오른쪽 재귀로 쓰면 <code>10−(2−3) = 11</code> 이 됩니다 — 뺄셈·나눗셈에서만 드러나는 함정이라 덧셈으로만 테스트하면 못 잡습니다.\n⚠️ 괄호는 <code>factor</code> 안에서 <code>expr</code> 를 다시 부르는 <b>상호 재귀</b>로 처리됩니다. 이 되부름이 중첩 괄호를 공짜로 처리해 줍니다.\n🔧 진짜 컴파일러의 파서도 구조는 같습니다 — 값을 바로 계산하는 대신 <b>AST 노드를 만들어</b> 돌려줄 뿐입니다. 이 계산기에서 <code>return v</code> 를 <code>return {op, left, right}</code> 로 바꾸면 파서가 됩니다."},{"t":"code","run":"js","k":"션팅 야드와 후위 계산","cat":"internals","q":"<b>션팅 야드</b> 알고리즘을 구현하세요. <code>toPostfix(s)</code> 는 공백으로 구분된 중위 표기식을 후위 표기로 바꿉니다(<code>* /</code> 가 <code>+ -</code> 보다 우선, 같은 우선순위는 좌결합, 괄호 지원). <code>evalPostfix(s)</code> 는 후위 표기를 스택으로 계산합니다 — <b>pop 순서에 주의</b>: 먼저 pop 한 것이 <b>오른쪽</b> 피연산자입니다.","src":"function toPostfix(s) {\n  // TODO: 연산자 스택으로 변환\n  return s;\n}\n\nfunction evalPostfix(s) {\n  // TODO: 스택 계산 — pop 순서 주의\n  return 0;\n}","sol":"function toPostfix(s) {\n  const prec = { '+': 1, '-': 1, '*': 2, '/': 2 };\n  const out = [], ops = [];\n  s.split(' ').forEach((t) => {\n    if (t === '(') ops.push(t);\n    else if (t === ')') { while (ops[ops.length - 1] !== '(') out.push(ops.pop()); ops.pop(); }\n    else if (prec[t]) {\n      while (ops.length && prec[ops[ops.length - 1]] >= prec[t]) out.push(ops.pop());\n      ops.push(t);\n    } else out.push(t);\n  });\n  return out.concat(ops.reverse()).join(' ');\n}\n\nfunction evalPostfix(s) {\n  const st = [];\n  s.split(' ').forEach((t) => {\n    if (t.length === 1 && '+-*/'.includes(t)) {\n      const b = st.pop(), a = st.pop();\n      st.push(t === '+' ? a + b : t === '-' ? a - b : t === '*' ? a * b : a / b);\n    } else st.push(Number(t));\n  });\n  return st[0];\n}","tests":[{"in":"toPostfix('3 + 4 * 2')","out":"'3 4 2 * +'"},{"in":"toPostfix('( 1 + 2 ) * 3')","out":"'1 2 + 3 *'"},{"in":"evalPostfix('10 2 -')","out":"8"},{"in":"evalPostfix('5 1 2 + 4 * + 3 -')","out":"14"}],"edge":[{"in":"toPostfix('1 - 2 - 3')","out":"'1 2 - 3 -'"},{"in":"evalPostfix('6 2 /')","out":"3"}],"ex":"🎯 후위 표기의 매력은 <b>괄호와 우선순위가 사라진다</b>는 것입니다. 변환할 때 이미 순서가 결정되어, 계산기는 스택 하나로 왼쪽에서 오른쪽으로 읽기만 하면 됩니다.\n💡 변환 규칙의 핵심은 '<b>스택 위의 연산자가 나보다 세거나 같으면 먼저 내보낸다</b>' 입니다. '같으면' 이 좌결합을 만듭니다 — <code>1 - 2 - 3</code> 이 <code>1 2 - 3 -</code> 이 되는 이유입니다. <code>&gt;=</code> 를 <code>&gt;</code> 로 바꾸면 우결합이 되어 답이 달라집니다.\n⚠️ 계산에서 가장 흔한 버그는 <b>pop 순서</b>입니다. 먼저 pop 한 값이 <b>오른쪽</b> 피연산자라 <code>a - b</code> 의 a 는 <b>두 번째</b> pop 입니다. 덧셈·곱셈은 교환법칙 때문에 버그가 숨고, 뺄셈에서야 드러납니다.\n🔧 JVM·파이썬 바이트코드가 정확히 이 구조의 스택 머신입니다. 컴파일 = 중위(사람의 표기) → 후위(기계의 순서) 변환이라는 감각을 이 문제로 얻을 수 있습니다."}]}]}]);
